(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c44"]=[{"id":"00002114","register_sub_id":"101","register_pk":"103104","name":"川端家住宅主屋","kana":"かわばたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県藤岡市立石新田391","lat":36.282059,"lng":139.099915,"geo_status":"db","era":"江戸後期／明治前期改造","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積218㎡","structure_material":"木造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"10 － 0059","desc":"川端家は旧中山道の街村集落である立石新田の豪農で，かつては一町屋敷とも呼ばれた。南北棟の主屋は屋敷南側に建ち，骨格は江戸後期の民家で，街道側の土間側を２階建に改造したのは明治前期頃と思われる。この地域の民家の変遷の一面をよくあらわしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002114"},{"id":"00002130","register_sub_id":"101","register_pk":"103120","name":"川端家住宅中門","kana":"かわばたけじゅうたくちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県藤岡市立石新田391","lat":36.28206656,"lng":139.10011614,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、間口2.2m","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"10 － 0075","desc":"別荘の玄関正面に建つ１間１戸腕木門。親柱を貫で結び，柱頂部で直接化粧棟木を受ける。貫上の小壁には木瓜形をモチーフとした板欄間を入れ，軒を木舞打の疎垂木とし，切妻屋根は起りをつける。小規模ながら，数寄屋風の洗練された意匠の門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002130"},{"id":"00002129","register_sub_id":"101","register_pk":"103119","name":"川端家住宅西塀","kana":"かわばたけじゅうたくにしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県藤岡市立石新田391","lat":36.2822829,"lng":139.09990256,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"板塀、瓦葺、延長45m","structure_material":"板塀","registered":"2001.04.24(平成13.04.24)","register_no":"10 － 0074","desc":"敷地北面のほぼ南半分を囲う延長約４４．９ｍの高塀。構造形式や高さは，基本的に南塀と同じであるが，上部の漆喰壁と下部の縦板張の比例が異なる。南塀同様，明治４３年の水害で相当に破損したが同じ形式で復旧された。西側の敷地境を区切る構成要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002129"},{"id":"00002121","register_sub_id":"101","register_pk":"103111","name":"川端家住宅番頭部屋","kana":"かわばたけじゅうたくばんとうべや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県藤岡市立石新田391","lat":36.28193333,"lng":139.10018911,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"10 － 0066","desc":"大門北側にあり，南北棟で切妻造・桟瓦葺，内部畳敷の建物。敷地外の壁は漆喰塗，腰を簓子下見板張とするが，敷地内は真壁造で引違い建具を設け，鉄格子入の窓を大門側の妻面につける。建設年代は明治中期頃と考えられ，屋敷入口の構成要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002121"},{"id":"00002131","register_sub_id":"101","register_pk":"103121","name":"川端家住宅東内塀","kana":"かわばたけじゅうたくひがしうちべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県藤岡市立石新田391","lat":36.28206808,"lng":139.10028598,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"板塀、瓦葺、延長39m","structure_material":"板塀","registered":"2001.04.24(平成13.04.24)","register_no":"10 － 0076","desc":"中門から東に延び，直角に北に折れて敷地奥に続く延長約３８．６ｍの内塀。玉石積基礎の上に，地覆石と土台の間に飼石を据える。真壁造で，腕木で軒を受け，桟瓦を葺く。東面中央部の高低差を巧みに処理するなど，簡素ながら質の高さが伺われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002131"},{"id":"00002120","register_sub_id":"101","register_pk":"103110","name":"川端家住宅東穀蔵","kana":"かわばたけじゅうたくひがしこくぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県藤岡市立石新田391","lat":36.2818736,"lng":139.10004153,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積45㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"10 － 0065","desc":"敷地東面の南側，南穀蔵東端の北側にある南北棟で切妻造・桟瓦葺の土蔵。壁は漆喰塗で，腰は簓子下見板張，外側に鉄格子入の窓を２つ設ける。建設年代は別荘と同じ明治中期頃と考えられ，大門を挟んで対をなす番頭部屋とともに，屋敷の入口を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002120"},{"id":"00002115","register_sub_id":"101","register_pk":"103105","name":"川端家住宅別荘","kana":"かわばたけじゅうたくべっそう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県藤岡市立石新田391","lat":36.282177,"lng":139.100266,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積131㎡","structure_material":"木造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"10 － 0060","desc":"別荘は広大な屋敷地のほぼ中央，主屋の背後に建つ。川端家が生糸関係で財を成した明治中期頃に，接客用の離れとしてつくられた。総２階建，桟瓦葺・入母屋造屋根の堂々たる外観であるが，良材をもちい，造作から壁に至るまで質の高いつくりの近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002115"},{"id":"00002122","register_sub_id":"101","register_pk":"103112","name":"川端家住宅味噌蔵","kana":"かわばたけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県藤岡市立石新田391","lat":36.28195902,"lng":139.10025,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積40㎡","structure_material":"木造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"10 － 0067","desc":"番頭部屋の北側にある２階建の土蔵。南北棟で切妻造・桟瓦葺，南妻面は番頭部屋と接している。壁は漆喰塗で，敷地外の腰を簓子下見板張とし，敷地内の西面には吹放しの庇を設ける。建設年代は明治前期頃と考えられ，屋敷東面の構えの際だった存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002122"},{"id":"00002132","register_sub_id":"101","register_pk":"103122","name":"川端家住宅南内塀","kana":"かわばたけじゅうたくみなみうちべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県藤岡市立石新田391","lat":36.28209084,"lng":139.10007544,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"板塀、瓦葺、延長2.9m","structure_material":"板塀","registered":"2001.04.24(平成13.04.24)","register_no":"10 － 0077","desc":"中門の西，南北棟の延長約２．９ｍの内塀。主屋の北東端部と中門を結ぶ位置にあり，前庭部と内庭部を画する役割を果たしている。構造形式は東内塀と同じく下段を縦板張，中段を鼠漆喰壁，上段を透かしとした構成で，瀟洒な数寄屋風の意匠をみせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002132"},{"id":"00002119","register_sub_id":"101","register_pk":"103109","name":"川端家住宅南穀蔵","kana":"かわばたけじゅうたくみなみこくぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県藤岡市立石新田391","lat":36.28192316,"lng":139.09995256,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"10 － 0064","desc":"敷地南面のほぼ東半分を占めて建つ。東西棟・桟瓦葺の長大な土蔵で，東妻は寄棟造，西妻は切妻造である。漆喰壁で，腰は外側を簓子下見板張，内側を煉瓦積とする。他に比べて全体にたちが低い建物で，建設年代は別荘と同じ明治中期頃と考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002119"},{"id":"00002128","register_sub_id":"101","register_pk":"103118","name":"川端家住宅南塀","kana":"かわばたけじゅうたくみなみべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県藤岡市立石新田391","lat":36.28212012,"lng":139.09976181,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"板塀、瓦葺、延長15m","structure_material":"板塀","registered":"2001.04.24(平成13.04.24)","register_no":"10 － 0073","desc":"敷地南面のほぼ西半分を囲う延長約１５．１ｍの高塀。玉石で築いた基礎の上に，地覆石を据えて，真壁造の軸部を建てる。屋根は腕木で板軒を受け，桟瓦を葺く。明治４３年の水害で相当に破損したが同じ形式で復旧された。屋敷南の旧道側を区切る構成要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002128"},{"id":"00002123","register_sub_id":"101","register_pk":"103113","name":"川端家住宅物置","kana":"かわばたけじゅうたくものおき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県藤岡市立石新田391","lat":36.282066,"lng":139.100433,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"10 － 0068","desc":"屋敷東面のほぼ中央にあり，南北棟の切妻造・桟瓦葺の平屋建で，敷地内の西面に吹放しの庇を設ける。長柱を用いて高い位置に和小屋を組み，内部板敷として，多様な物を収納する内部空間とする。味噌蔵などとともに屋敷東面の一連の構えをつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002123"},{"id":"00002125","register_sub_id":"101","register_pk":"103115","name":"川端家住宅湯殿","kana":"かわばたけじゅうたくゆどの","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県藤岡市立石新田391","lat":36.28209862,"lng":139.09980885,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積9.9㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"10 － 0070","desc":"主屋の西側，土間部の背面に位置している。南北棟で切妻造・桟瓦葺，真壁造の建物で，開口部にガラス戸を多く用いている。桁行をほぼ中央で間仕切り，南側を脱衣室，北側に風呂釜を設ける。小規模であるが，生活空間を物語る数少ない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002125"},{"id":"00006160","register_sub_id":"101","register_pk":"107144","name":"神戸家住宅座敷蔵（双渓堂）","kana":"かんべけじゅうたくざしきぐら（そうけいどう）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県甘楽郡下仁田町大字本宿3638-1","lat":36.24297564,"lng":138.71024225,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積76㎡","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"10 － 0232","desc":"旧中山道脇往還下仁田道に北面する敷地の南寄りに位置する。木造２階建の塗屋で，屋根は切妻造，桟瓦葺とする。１階は床飾りを備えた座敷等８畳３室とし，南に縁と土庇が付く。２階は１室の物入とする。外壁は白漆喰を軒裏まで塗上げ，腰の海鼠壁が目をひく。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006160"},{"id":"00015408","register_sub_id":"101","register_pk":"533423","name":"旧相川家住宅稲荷社","kana":"きゅうあいかわけじゅうたくいなりしゃ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県伊勢崎市三光町6-11","lat":36.31865278,"lng":139.191475,"geo_status":"db","era":"明治15年","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積5.1㎡","structure_material":"土蔵造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"10 - 0370","desc":"敷地北西隅に東面して建つ屋敷神である。土蔵造入母屋造妻入桟瓦葺で、大棟は組棟で高く積み神紋を飾る。戸口に両開の掛子塗戸と桟唐戸を吊り、内部は拝所の奥に祭壇を雛壇状に設け、最上段正面に桟唐戸を吊る。土蔵造で重厚な外観とした珍しい小社である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015408"},{"id":"00015410","register_sub_id":"101","register_pk":"533425","name":"旧相川家住宅裏門及び塀","kana":"きゅうあいかわけじゅうたくうらもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県伊勢崎市三光町6-17","lat":36.31841111,"lng":139.19132778,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"裏門 木造、瓦葺、間口2.1m 塀 木造、瓦葺、総延長25m","structure_material":"裏門 木造","registered":"2025.08.06(令和7.08.06)","register_no":"10 - 0372","desc":"敷地南の小路に面し、西側を画す腕木門及び塀。裏門は切妻造桟瓦葺で、一軒疎垂木とする。両開の板扉は竪板を目隙に張る。東西に延びる板塀は裏門に斜めに取付き門前に引きをつくる。外壁は土壁で腰下見板張、屋根桟瓦葺である。小路側の屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015410"},{"id":"00015409","register_sub_id":"101","register_pk":"533424","name":"旧相川家住宅表門及び塀","kana":"きゅうあいかわけじゅうたくおもてもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県伊勢崎市三光町6-11","lat":36.31851389,"lng":139.19162778,"geo_status":"db","era":"明治33年","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"表門 木造、瓦葺、間口2.4m 塀 木造、瓦葺、総延長14m","structure_material":"表門 木造","registered":"2025.08.06(令和7.08.06)","register_no":"10 - 0371","desc":"店舗の南に続き、敷地東面を画す薬医門と塀。表門は起付き切妻造本瓦葺で大棟は七宝繋の透積、左右に本瓦葺板塀を付す。内部は天井を張り、板扉を八双金具で飾る。南に続く板塀は桟瓦葺で壁は白漆喰塗、腰下見板張とし、重厚な表門とともに屋敷構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015409"},{"id":"00015406","register_sub_id":"101","register_pk":"533421","name":"旧相川家住宅主屋","kana":"きゅうあいかわけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県伊勢崎市三光町6-11","lat":36.31862778,"lng":139.19148611,"geo_status":"db","era":"天保8年（1837）／昭和33年頃、平成12年改修","year":1837,"year_source":"db","year_min":1837,"year_max":1837,"year_label":null,"structure":"木造平屋建、鉄板葺一部瓦葺、建築面積100㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"10 - 0368","desc":"店舗の西に接続する主屋である。平屋建切妻造鉄板葺南北棟の南東に入母屋造屋根の式台と内玄関を構える。内部は南から取次、中の間八畳、北西に上段の間八畳を矩折に並べ、上段の間南面に一間幅の畳敷入側を付す。床構えの造作など、丁寧な書院座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015406"},{"id":"00015405","register_sub_id":"101","register_pk":"533420","name":"旧相川家住宅旧店舗","kana":"きゅうあいかわけじゅうたくきゅうてんぽ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"江戸","pref":"群馬県","address":"群馬県伊勢崎市三光町6-11","lat":36.3186,"lng":139.19160556,"geo_status":"db","era":"江戸後期／昭和中期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積44㎡","structure_material":"土蔵造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"10 - 0367","desc":"西町の通り西側に位置する旧金物商の旧店舗。土蔵造二階建切妻造平入桟瓦葺で南に下屋を付し、外壁漆喰塗仕上とする。各階一室で一階は事務所、二階は会議室とし、上部には登梁形式の小屋組を現す。建ちの低い外観で敷地北東の歴史的な景観を形成する旧店舗。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015405"},{"id":"00015407","register_sub_id":"101","register_pk":"533422","name":"旧相川家住宅土蔵","kana":"きゅうあいかわけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県伊勢崎市三光町6-11","lat":36.31866111,"lng":139.19146944,"geo_status":"db","era":"天保15年（1844）","year":1844,"year_source":"db","year_min":1844,"year_max":1844,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積54㎡","structure_material":"土蔵造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"10 - 0369","desc":"主屋の北に建つ土蔵造二階建、切妻造桟瓦葺東西棟の旧金物蔵である。南面西寄りに戸口を開き主屋北面西端に接続する。東妻と二階南面に窓を開き、漆喰塗の扉を吊る。各階一室の板敷で小屋は登梁を水平の繋梁で繋ぐ。長大な外観で敷地北方の景観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015407"},{"id":"00006316","register_sub_id":"101","register_pk":"107299","name":"旧今泉家住宅表門","kana":"きゅういまいずみけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県みどり市東町花輪96","lat":36.51958235,"lng":139.30810531,"geo_status":"db","era":"江戸末期／平成18改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口3.8m、潜戸及び袖塀付","structure_material":"木造","registered":"2007.10.02(平成19.10.02)","register_no":"10 － 0244","desc":"主屋の南側に、通りから３ｍほど後退して建つ。間口２．３ｍ、切妻造、桟瓦葺の腕木門で、背面に控柱を建て、西側に潜戸、東に袖塀を付ける。比較的大きい屋根には緩やかな起りをつけ、棟込み瓦を青海波に積むなど丁寧なつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006316"},{"id":"00006315","register_sub_id":"101","register_pk":"107298","name":"旧今泉家住宅蔵","kana":"きゅういまいずみけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県みどり市東町花輪96","lat":36.51974776,"lng":139.30796334,"geo_status":"db","era":"大正4／平成18改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積17㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"10 － 0243","desc":"敷地のほぼ中央、主屋背後に南面して建つ。桁行２間半、梁間１間半規模の、切妻造妻入とする２階建の土蔵。正面に入口を設け庇を掛け、側面に鉄格子を付けた窓をあける。外壁は鉢巻を含め、石積風目地を付けたモルタル塗洗出しで仕上げ、簡潔かつ重厚である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006315"},{"id":"00006314","register_sub_id":"101","register_pk":"107297","name":"旧今泉家住宅主屋","kana":"きゅういまいずみけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県みどり市東町花輪96","lat":36.51966144,"lng":139.30805757,"geo_status":"db","era":"江戸末期／平成18改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階一部平屋建、鉄板葺、建築面積94㎡","structure_material":"木造2階一部平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"10 － 0242","desc":"市北部の旧東村の中心部に位置する。桁行６間、梁間４間半規模の、切妻造平入の木造２階一部平屋建で、背面屋根を葺き降ろす。真壁造の漆喰仕上げで、腰を下見板張及び簓子下見板張。南面して建ち、正面に下屋を設け、中央に式台を構える。軽快な意匠の住宅建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006314"},{"id":"00006317","register_sub_id":"101","register_pk":"107300","name":"旧今泉家住宅塀","kana":"きゅういまいずみけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県みどり市東町花輪96","lat":36.51959362,"lng":139.30812059,"geo_status":"db","era":"江戸末期／平成18改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、延長36m","structure_material":"木造","registered":"2007.10.02(平成19.10.02)","register_no":"10 － 0245","desc":"南北に長い矩形の敷地南側に築かれる。表門両袖から折れ曲がり、旧銅山街道に面する、桟瓦葺、腰簓子下見板張の南塀と、その西端から北側に接続する腰竪板張で、横連子窓を開ける西塀からなり、南塀両端部に鬼板を付ける。表門と一体となり風格ある外観を呈す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006317"},{"id":"00005246","register_sub_id":"101","register_pk":"106234","name":"旧尾関家住宅主屋","kana":"きゅうおぜきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市宮本町2-3-27","lat":36.41958423,"lng":139.33736414,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積98㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"10 － 0150","desc":"北西角の敷地に北面して建つ和風住宅で，玄関脇に洋風の書斎１室を付す。主屋は東西棟の寄棟造，桟瓦葺で，６畳２室と８畳に台所等が付く。書斎は切妻造，フランス瓦葺で，北に妻を見せ，鎧下見板張の外壁に縦長の引違窓を開く。昭和初期住宅地の遺構例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005246"},{"id":"00012294","register_sub_id":"101","register_pk":"531618","name":"旧狩宿茶屋本陣","kana":"きゅうかりやどちゃやほんじん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"群馬県","address":"群馬県吾妻郡長野原町大字応桑字新田28-1","lat":36.51065833,"lng":138.59720278,"geo_status":"db","era":"江戸後期／明治18年増築、昭和48年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、金属板葺、建築面積172㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"10-0342","desc":"旧信州街道の狩宿宿に残る名主宅の主屋。切妻造平入で、二階床と屋根の軒を出桁で張出す。土間部は撤去されたが床上部三列が残る。上手に座敷三室を並べ、最奥部の上段の間は柱にエンジュを用い、中の間境に筬欄間を入れる。脇往還･茶屋本陣の数少ない遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012294"},{"id":"00000343","register_sub_id":"101","register_pk":"101333","name":"旧土岐家住宅洋館","kana":"きゅうときけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県沼田市都市計画事業沼田市中心市街地土地区画整理事業２－２街区１１６０－１他","lat":36.64526667,"lng":139.047725,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造3階建，スレート葺，建築面積119㎡","structure_material":"木造3階建","registered":"1997.11.05(平成9.11.05)","register_no":"10 － 0022","desc":"江戸時代に沼田藩主を勤めた土岐家の東京渋谷にあった邸宅の洋館部を，平成２年に現在地に移築したもの。ドイツ下見やアーチ窓を用いる等，外観は洋風だが，内部は和風と洋風の両方の接客室をもつ。大正期の大邸宅に建てられた洋館の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000343"},{"id":"00010562","register_sub_id":"101","register_pk":"201136","name":"旧堀家住宅蔵","kana":"きゅうほりけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市巴町一丁目字柿ノ木1117-1","lat":36.409349,"lng":139.33538,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積19㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"10－0324","desc":"主屋玄関の北に建つ二階建の蔵。建ちの高い土蔵風の外観だが、鉄筋コンクリート造で、内部に柱形や梁を見せる。小屋は梁を渡した上に棟束を立て、登梁で屋根を支えるなど木造軸組を思わせる架構を見せる。昭和初期の鉄筋コンクリート造建築の一例として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010562"},{"id":"00010561","register_sub_id":"101","register_pk":"201135","name":"旧堀家住宅主屋","kana":"きゅうほりけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市巴町一丁目字柿ノ木1117-1","lat":36.409274,"lng":139.335483,"geo_status":"db","era":"昭和2年／平成20年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積278㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"10－0323","desc":"桐生屈指の織物工場の経営者の住宅。木造平屋建で西面中央に入母屋の玄関を構え、南に外壁モルタル塗の洋室、北に蔵を並べる。南面は庭に面して和室を配する。洋室はレリーフや出窓下部に昭和初期らしいアールデコ装飾を見せる。洗練された意匠の洋間付住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010561"},{"id":"00012494","register_sub_id":"101","register_pk":"367789","name":"群馬県立富岡高等学校御殿（旧七日市藩陣屋正殿）","kana":"ぐんまけんりつとみおかこうとうがっこうごてん（きゅうなのかいちはんじんやせいでん）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"群馬県","address":"群馬県富岡市七日市1425-1","lat":36.255638,"lng":138.87326,"geo_status":"geocoded","era":"天保14年（1843）／明治7年改修、昭和7年・同51年移築","year":1843,"year_source":"db","year_min":1843,"year_max":1843,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積361㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"10 － 0343","desc":"もと七日市藩陣屋正殿で構内東北辺に建つ。東西棟の入母屋造で、北面中央に入母屋造の式台玄関を構える。内部は入側を室内に取込む改変があるが、軸部や造作をよく留める。玄関の妻飾は虹梁大瓶束を出組で持出すなど、御殿に相応しい風格ある意匠をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012494"},{"id":"00012495","register_sub_id":"101","register_pk":"367790","name":"群馬県立富岡高等学校御殿黒門（旧七日市藩陣屋中門）","kana":"ぐんまけんりつとみおかこうとうがっこうごてんくろもん（きゅうなのかいちはんじんやちゅうもん）","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県富岡市七日市1425-1","lat":36.255638,"lng":138.87326,"geo_status":"geocoded","era":"天保14年（1843）／明治8年・大正14年・昭和7年移築","year":1843,"year_source":"db","year_min":1843,"year_max":1843,"year_label":null,"structure":"木造、瓦葺、間口3.2m","structure_material":"木造","registered":"2018.11.02(平成30.11.02)","register_no":"10 － 0344","desc":"もと七日市藩陣屋中門で敷地東面に開く。間口３・２メートルの切妻造桟瓦葺、棟門形式で、五平の柱を立て、肘木付の腕木で軒桁を受けて深い軒をつくり、背面桁を控柱で受ける。重厚な趣を呈し、妻飾の蕪懸魚に梅鉢の六葉など御殿と共通する細部意匠をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012495"},{"id":"00001037","register_sub_id":"101","register_pk":"102027","name":"光恩寺庫裏","kana":"こうおんじくり","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"群馬県","address":"群馬県邑楽郡千代田町大字赤岩甲1041","lat":36.20817841,"lng":139.43958872,"geo_status":"db","era":"江戸時代末期／明治20代移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸時代末期","structure":"木造平屋建，瓦葺，建築面積400㎡","structure_material":"木造平屋建","registered":"1999.02.17(平成11.02.17)","register_no":"10 － 0036","desc":"長屋門の背後，本堂寄りの位置に大きな妻を見せて建つ。檀家である豪農の主屋を，長屋門と同様に，館林から移築して庫裏としたもので、妻の架構に特徴がある。主たる檀家の居住地を物語る建造物で，寺の来歴を知るうえで貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001037"},{"id":"00001036","register_sub_id":"101","register_pk":"102026","name":"光恩寺長屋門","kana":"こうおんじながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県邑楽郡千代田町大字赤岩甲1041","lat":36.20791503,"lng":139.43953385,"geo_status":"db","era":"江戸時代末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸時代末期","structure":"木造平屋建，瓦葺，建築面積83㎡","structure_material":"木造平屋建","registered":"1999.02.17(平成11.02.17)","register_no":"10 － 0035","desc":"寄棟瓦葺，真壁造りの素朴な長屋門。檀家の斡旋により埼玉県妻沼町の荻野家から明治２０年頃に移築したもの。日本で最初の女医となった荻野吟子の生家の長屋門として知られる。庫裏に通じる通用門としての役割を果たしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001036"},{"id":"00005411","register_sub_id":"101","register_pk":"106399","name":"後藤織物奥座敷","kana":"ごとうおりものおくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県桐生市東一丁目730","lat":36.41118403,"lng":139.34584142,"geo_status":"db","era":"大正14頃","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積97㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"10 － 0160","desc":"主屋の西方に接続する接客用座敷。桁行６間半梁行４間規模，寄棟造，桟瓦葺の木造平屋建で，１０畳と床・棚・付書院をもつ１２畳半の２室から成り，南面と北面に廊下を設ける。南面主屋寄りに入母屋造の玄関をもち，現在は帯地の陳列場として使用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005411"},{"id":"00005410","register_sub_id":"101","register_pk":"106398","name":"後藤織物主屋","kana":"ごとうおりものしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県桐生市東一丁目730","lat":36.411114,"lng":139.346054,"geo_status":"db","era":"明治前期／大正14頃増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、鉄板葺、建築面積226㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"10 － 0159","desc":"工場敷地の南方に建つ。東方を土間，西方を床上部とした桁行６間半，梁行４間規模の木造２階建。背面北側と東側桁行１間半分を大正１４年頃に増築。現在は土間部を事務所，床上部を仕事場として使用する。機業主住居から事務所兼作業場へ転換された建造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005410"},{"id":"00002009","register_sub_id":"101","register_pk":"102999","name":"小見家住宅（水村園）隠居屋","kana":"こみけじゅうたく（みずむらえん）いんきょや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県高崎市本町123-1","lat":36.330906,"lng":139.003174,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、亜鉛葺、建築面積36㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"10 － 0051","desc":"敷地の東北隅に建つ桁行４間，梁行２間半規模の木造２階建，南北棟，寄棟造，桟瓦葺建屋で，２階を８畳と４畳半の隠居部屋とし，西北端から幅半間，長２間の廊下を西方に突出し，２階西端に便所を置く。水村園における住居構成の変遷を物語る遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002009"},{"id":"00002003","register_sub_id":"101","register_pk":"102993","name":"小見家住宅（水村園）着物蔵","kana":"こみけじゅうたく（みずむらえん）きものぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県高崎市本町123-1","lat":36.33069078,"lng":139.00313004,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積17㎡","structure_material":"土蔵造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"10 － 0045","desc":"新座敷の北妻面に接して建つ。桁行２間半，梁行１間半規模，南北棟，切妻造，桟瓦葺の平入２階建土蔵で，東面を戸前とする。規模的には土蔵群の中で一番小さいが，棟の高さは新蔵に次いで高く，防火帯としての土蔵群の中核的位置を占める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002003"},{"id":"00002002","register_sub_id":"101","register_pk":"102992","name":"小見家住宅（水村園）新座敷","kana":"こみけじゅうたく（みずむらえん）しんざしき","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県高崎市本町123-1","lat":36.330639,"lng":139.00312944,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積22㎡","structure_material":"土蔵造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"10 － 0044","desc":"水村園は幕末期創業の老舗の茶舗で，高崎城下町時代の町割である間口９．６ｍ，奥行４６ｍの南北に細長い敷地に土蔵群を棟を接して建ち並べる。新座敷は，防火壁としての役割を担った土蔵群の南端に位置する１０畳規模の座敷蔵で，初代の隠居屋と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002002"},{"id":"00002004","register_sub_id":"101","register_pk":"102994","name":"小見家住宅（水村園）味噌蔵","kana":"こみけじゅうたく（みずむらえん）みそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県高崎市本町123-1","lat":36.33073,"lng":139.003128,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、亜鉛葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"10 － 0046","desc":"着物蔵の北方に位置し，着物蔵北妻面との間１間幅のところに蔵前を設ける。桁行３間半，梁行２間半規模，南北棟，切妻造，鉄板葺の２階建土蔵で，道路拡幅により失われた店蔵及び主屋寄りに在って，新座敷・着物蔵とともに屋敷構えにおける内向部を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002004"},{"id":"00002007","register_sub_id":"101","register_pk":"102997","name":"小見家住宅（水村園）湯殿","kana":"こみけじゅうたく（みずむらえん）ゆどの","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県高崎市本町123-1","lat":36.330647,"lng":139.003174,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"煉瓦造平屋建、瓦葺、建築面積12㎡","structure_material":"煉瓦造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"10 － 0049","desc":"敷地の東辺沿い，新座敷に向きあう位置に建つ。境界塀を兼ねる煉瓦造防火壁から西方に長１間の煉瓦壁を３枚建てて，風呂場・ボイラー室・便所の間仕切壁とし，桟瓦葺の寄棟屋根を架ける。便益施設とはいえ，フランス積にするなど丁寧な仕事ぶりが窺われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002007"},{"id":"00003807","register_sub_id":"101","register_pk":"104797","name":"小茂田家住宅井戸屋","kana":"こもだけじゅうたくいどや","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県伊勢崎市長沼町2631","lat":36.26271957,"lng":139.21212761,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、鉄板葺、建築面積9.8㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"10 － 0105","desc":"主屋の北方に位置する。東辺に斜路を付けた石積基壇の中央西寄りに井戸側，中央北寄りに洗場を配し，四方転びの柱に寄棟屋根を載せる。桁行２間梁間１間半と規模も大きく，蚕種・養蚕農家の屋敷構えを形づくる上で欠くことのできない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003807"},{"id":"00003806","register_sub_id":"101","register_pk":"104796","name":"小茂田家住宅蔵","kana":"こもだけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県伊勢崎市長沼町2631","lat":36.26285612,"lng":139.21203482,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積62㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"10 － 0104","desc":"主屋の北西方に位置する。桁行５間梁間２間半，東西棟，切妻造，桟瓦葺，平入の２階建土蔵の東妻面に，桁行２間半奥行２間の片流造味噌部屋を付ける。小屋組はキングポストトラスで，棟方向と陸梁上に斜材を入れる。スチールサッシに網入りガラスの窓も特色。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003806"},{"id":"00003804","register_sub_id":"101","register_pk":"104794","name":"小茂田家住宅主屋","kana":"こもだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県伊勢崎市長沼町2631","lat":36.26262159,"lng":139.21217719,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積278㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"10 － 0102","desc":"屋敷地中央に南面して建つ。桁行１０間梁間５間，切妻造，桟瓦葺の木造２階建を主体部とし，北面に１間幅の下屋，西面に片寄棟造の２階建を付ける。２階を蚕室とし，棟に３カ所の越屋根を上げた「三ツ櫓」は蚕種・養蚕先進地の象徴的存在になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003804"},{"id":"00006625","register_sub_id":"101","register_pk":"107608","name":"里見家住宅蔵","kana":"さとみけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県甘楽郡下仁田町大字下小坂字竹ノ鼻48","lat":36.21884673,"lng":138.77878459,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"10 － 0249","desc":"敷地東南に建つ、桁行３間梁間２間半の２階建土蔵。切妻造桟瓦葺の置屋根は、もとは石置板葺であった。外壁は白漆喰仕上げとする。西面妻側に庇を設け、両開の掛子塗戸をたて出入口とし、２階北側面に窓を開ける。簡明な意匠で、敷地景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006625"},{"id":"00006624","register_sub_id":"101","register_pk":"107607","name":"里見家住宅主屋","kana":"さとみけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県甘楽郡下仁田町大字下小坂字竹ノ鼻48","lat":36.21899888,"lng":138.77863281,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積176㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"10 － 0248","desc":"桁行１８ｍ梁間９．５ｍと大規模な２階建で敷地北側に南面して建つ。切妻造桟瓦葺とし、換気のための越屋根を棟に２ヶ所設ける。１階は土間と６室の床上からなる居住部分。２階全体は当初は１室で養蚕に利用された。近代の大型養蚕農家の特徴をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006624"},{"id":"00006626","register_sub_id":"101","register_pk":"107609","name":"里見家住宅味噌蔵","kana":"さとみけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県甘楽郡下仁田町大字下小坂字竹ノ鼻48","lat":36.21884863,"lng":138.77852129,"geo_status":"db","era":"江戸末期／大正4改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積17㎡","structure_material":"土蔵造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"10 － 0250","desc":"主屋の正面やや西寄り建つ土蔵造２階建で、桁行２間半梁間２間の規模になる。切妻造桟瓦葺で、もとは石置板葺屋根であった。東面に戸口を設ける妻入で、通りに面する南側に窓を２ヶ所開ける。１階を土間床、２階を板敷とする。装飾のない堅実な外観をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006626"},{"id":"00006627","register_sub_id":"101","register_pk":"107610","name":"里見家住宅門","kana":"さとみけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県甘楽郡下仁田町大字下小坂字竹ノ鼻48","lat":36.21884919,"lng":138.77858108,"geo_status":"db","era":"江戸末期／大正4改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、建築面積13㎡","structure_material":"木造","registered":"2007.12.05(平成19.12.05)","register_no":"10 － 0251","desc":"味噌蔵の東に隣接して南面して建つ切妻造桟瓦葺で、上部に物入を設け、櫓門風の外観を造る。桁行４．３ｍ梁間３．１ｍ、正面中央に出入口、両側に板壁を設ける。上部物入は正面側に張り出し、外観を真壁造とする。味噌蔵と一体となり、屋敷の正面構えを造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006627"},{"id":"00002517","register_sub_id":"101","register_pk":"103507","name":"重田家住宅井戸屋形","kana":"しげたけじゅうたくいどやかた","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県佐波郡玉村町大字小泉42","lat":36.296944,"lng":139.15349058,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積7.4㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"10 － 0094","desc":"主屋の東方，東の蔵の西南に位置する。約３ｍ四方の亀甲積石積基壇の上に建つ。ころびをつけた４本柱の上部を頭貫と方杖とにより固め，南北棟，切妻造，桟瓦葺の屋根を架ける。屋敷構に欠くことのできない構成要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002517"},{"id":"00002518","register_sub_id":"101","register_pk":"103508","name":"重田家住宅表門及び塀","kana":"しげたけじゅうたくおもてもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県佐波郡玉村町大字小泉42","lat":36.29691524,"lng":139.15306334,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、石造及び木造塀延長80m付","structure_material":"木造","registered":"2001.11.20(平成13.11.20)","register_no":"10 － 0095","desc":"門は主屋玄関の南方に位置する間口約３ｍほどの１間１戸の薬医門で，両脇には通用口を開ける。敷地南辺沿いの塀は石積基壇の上に載った桟瓦葺の板塀で，門及び塀越しの主屋，蔵，樹木などとともに庄屋屋敷風の屋敷景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002518"},{"id":"00002513","register_sub_id":"101","register_pk":"103503","name":"重田家住宅穀蔵","kana":"しげたけじゅうたくこくぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県佐波郡玉村町大字小泉42","lat":36.297054,"lng":139.153641,"geo_status":"db","era":"明治25頃","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"土蔵造平屋建、鉄板葺、建築面積33㎡","structure_material":"土蔵造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"10 － 0090","desc":"利根川右岸近くに位置する敷地の東北方，主屋背面側の台所の東方に建つ。桁行４間，梁間２間半規模，切妻造，鉄板葺，平入の平屋建土蔵で，南面に庇をつけて入口をとる。北面に窓を開けただけの閉鎖的な造りで，穀蔵とされる。屋敷地の主要構成要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002513"},{"id":"00002512","register_sub_id":"101","register_pk":"103502","name":"重田家住宅主屋","kana":"しげたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県佐波郡玉村町大字小泉42","lat":36.297012,"lng":139.153381,"geo_status":"db","era":"明治16","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造2階建、瓦葺、建築面積207㎡","structure_material":"木造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"10 － 0089","desc":"代々医師を家業とした家柄の住宅兼診療所。桁行８間，梁間５間規模の切妻造，桟瓦葺，総２階建で，南と西の２面に下屋を架けて縁廊下を廻す。内部は６間取で，東側の土間に待合いを設け，その西側を診察室とする。正面ほぼ中央の式台玄関が当家の格式を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002512"},{"id":"00002515","register_sub_id":"101","register_pk":"103505","name":"重田家住宅外便所","kana":"しげたけじゅうたくそとべんじょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県佐波郡玉村町大字小泉42","lat":36.296951,"lng":139.153549,"geo_status":"db","era":"昭和1頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積5.8㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"10 － 0092","desc":"主屋東南方の庭先に建つ独立建家で，患者用の便所として建設。建坪２坪に満たない小屋であるが，南北棟，寄棟造，桟瓦葺で，外周を真壁造とした丁寧なつくりとする。診療所を兼ねた民家風住宅における患者用便所の在り方を示す実例のひとつとして貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002515"},{"id":"00002514","register_sub_id":"101","register_pk":"103504","name":"重田家住宅西の蔵","kana":"しげたけじゅうたくにしのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県佐波郡玉村町大字小泉42","lat":36.29710917,"lng":139.1532037,"geo_status":"db","era":"昭和1頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"10 － 0091","desc":"主屋の西方に建つ東西棟，切妻造，桟瓦葺，総２階建の家財蔵で，外部はモルタル洗出し仕上げとする。桁行４間，梁間２間半規模で北面に下屋を架けて蔵前とし，主屋北西隅に連絡する。階下東側は６畳規模の蔵座敷となっており，隠居部屋としての使用を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002514"},{"id":"00002516","register_sub_id":"101","register_pk":"103506","name":"重田家住宅東の蔵","kana":"しげたけじゅうたくひがしのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県佐波郡玉村町大字小泉42","lat":36.29700272,"lng":139.15357869,"geo_status":"db","era":"昭和3頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積9.9㎡","structure_material":"土蔵造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"10 － 0093","desc":"穀蔵の南方に建つ。桁行２間，梁間１間半規模，南北棟，切妻造，桟瓦葺，平入の平屋建土蔵で，外部は西の蔵と同様なモルタル洗出し仕上げとし，西面に庇をだして入口を設ける。小規模であるが，薬の材料蔵であり，診療所に不可欠な存在として重要。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002516"},{"id":"00003065","register_sub_id":"101","register_pk":"104055","name":"茂原家住宅隠居蔵","kana":"しげはらけじゅうたくいんきょぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県甘楽郡甘楽町大字小幡1445-1","lat":36.218952,"lng":138.918015,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造3階建、瓦葺、建築面積35㎡","structure_material":"土蔵造3階建","registered":"2003.01.31(平成15.01.31)","register_no":"10 － 0098","desc":"主屋の南西側に接して建つ。妻入の３階建土蔵で他の土蔵と異なり置屋根形式としていない。庭側に面する妻には下屋庇をかけ，２階３階に窓を開き，内部は１階を居室，２・３階を質倉として用いられる。敷地内建物の中でも特に重厚な外観を持つ土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003065"},{"id":"00003064","register_sub_id":"101","register_pk":"104054","name":"茂原家住宅米蔵","kana":"しげはらけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県甘楽郡甘楽町大字小幡1445-1","lat":36.21880783,"lng":138.9182375,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階一部3階建、瓦葺、建築面積55㎡","structure_material":"土蔵造2階一部3階建","registered":"2003.01.31(平成15.01.31)","register_no":"10 － 0097","desc":"主屋の南東に西面して建つ土蔵。内部は２階建とし，一部に３階を設けている。敷地側には全面に下屋をかけ，広い作業空間を生み出している。土蔵としては比較的規模が大きく，街路に面して敷地を画し，江戸時代の農村景観を今日に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003064"},{"id":"00003063","register_sub_id":"101","register_pk":"104053","name":"茂原家住宅主屋","kana":"しげはらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県甘楽郡甘楽町大字小幡1445-1","lat":36.218979,"lng":138.918182,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造2階建、瓦葺、建築面積207㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"10 － 0096","desc":"木造２階建，切妻造，桟瓦葺もと板葺，平入で，南面して建つ。１階は現在は田の字型を基本とするが，当初は三間取広間型平面であったと考えられ，２階は養蚕のために用いられる。養蚕を行う農家主屋の好例であると同時に，平面形態の変遷の点でも特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003063"},{"id":"00003066","register_sub_id":"101","register_pk":"104056","name":"茂原家住宅西蔵","kana":"しげはらけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県甘楽郡甘楽町大字小幡1445-1","lat":36.21887689,"lng":138.9179417,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"10 － 0099","desc":"隠居蔵の南西に隣接して建ち，屋敷地の南西隅を画す。土蔵造２階建，平入で置屋根形式とする。庭に面する東面に両開き扉を開き，扉上部には漆喰彫刻を設けている。建築年代は形式等から江戸末期と推定され，敷地の景観上欠くことのできない建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003066"},{"id":"00006024","register_sub_id":"101","register_pk":"107009","name":"島田家住宅主屋","kana":"しまだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県桐生市巴町1-1121-8","lat":36.40910631,"lng":139.336411,"geo_status":"db","era":"昭和28","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積91㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"10 － 0207","desc":"店舗の北に接続する木造平屋建，入母屋造，桟瓦葺で，Ｌ字形平面をもつ。西面の中庭側に入母屋屋根の玄関を突出する。内部は座敷１０畳と次の間６畳の西に縁を付け，洋間，台所などを配す。外壁は真壁造の白漆喰塗で，東街路側の景観の主要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006024"},{"id":"00006069","register_sub_id":"101","register_pk":"107054","name":"島田家住宅中門","kana":"しまだけじゅうたくちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県桐生市巴町1-1121-8","lat":36.40909931,"lng":139.33631342,"geo_status":"db","era":"昭和28","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造、銅板葺、間口1.2m","structure_material":"木造","registered":"2006.11.29(平成18.11.29)","register_no":"10 － 0208","desc":"主屋玄関前の中庭に面して設けた小規模な腕木門。両側に袖塀が付き，南が玄関に接続する。切妻屋根は銅板一文字葺で，緩い箕甲で形を整える。門柱や門口上枠を磨き丸太とし，小壁に下地窓を開き，上端櫛形の両開板戸を吊り，やや草庵風の趣を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006069"},{"id":"00006068","register_sub_id":"101","register_pk":"107053","name":"島田家住宅鳥居","kana":"しまだけじゅうたくとりい","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県桐生市巴町1-1121-8","lat":36.40913,"lng":139.336334,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"石造、高さ2.3m、幅2.8m","structure_material":"石造","registered":"2006.11.29(平成18.11.29)","register_no":"10 － 0209","desc":"中庭の中央やや北寄りに祀る稲荷社の東正面に建てられた，石造の明神鳥居である。幅２．８ｍ，全高２．３ｍの花崗岩製で，足元に八角形の礎石を据える。柱は径６寸で１石に造る。屋敷社の鳥居としては規模も大きく中庭の景観要素として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006068"},{"id":"00015284","register_sub_id":"101","register_pk":"532408","name":"下村家住宅稲荷社","kana":"しもむらけじゅうたくいなりしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県前橋市紅雲町一丁目245-26","lat":36.38464167,"lng":139.06023333,"geo_status":"db","era":"明治後期／昭和20年頃移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、鉄板葺、建築面積0.2㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"10 - 0358","desc":"敷地の北辺、主屋の西に南面する小祠。丸石積の基壇に建つ、一間社流見世棚造で軒は一軒疎垂木。平面規模に比して、螻羽が深い大振りの屋根を鉄板葺とする。身舎正面は板扉両開き、側面は連子窓、背面は横板壁とする。小規模ながら敷地景観をつくる小社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015284"},{"id":"00015283","register_sub_id":"101","register_pk":"532407","name":"下村家住宅主屋","kana":"しもむらけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県前橋市紅雲町一丁目245","lat":36.38455833,"lng":139.06035,"geo_status":"db","era":"江戸末期／昭和20年代改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積106㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"10 - 0357","desc":"前橋市街地の南部、利根川左岸に位置する旧家の旧別邸主屋。平家建寄棟造東西棟茅葺（鉄板仮葺）で北に台所棟、西に切妻屋根の便所を付す。南庭に面して三室並べ、西端北面に奥行浅く床を構える。南縁境は一間毎に柱を立てるなど古式で、軒が低い外観の主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015283"},{"id":"00003809","register_sub_id":"101","register_pk":"104799","name":"正田醤油文庫蔵","kana":"しょうだしょうゆぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県館林市栄町3-1","lat":36.24807509,"lng":139.52690095,"geo_status":"db","era":"江戸末期／昭和62移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"10 － 0107","desc":"記念館の北方に位置する。桁行２間半梁間２間規模，南北棟，切妻造，桟瓦葺の２階建土蔵で，南妻面に観音開の戸口を設け，２階に観音開防火戸を建て込んだ窓を開ける。記念館としての旧店舗とともに現在地に移築され，記念館の収蔵庫として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003809"},{"id":"00002213","register_sub_id":"101","register_pk":"103203","name":"水琴亭","kana":"すいきんてい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県高崎市吉井町岩崎2229","lat":36.282597,"lng":138.997391,"geo_status":"db","era":"昭和10／平成2移築","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積158㎡","structure_material":"木造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"10 － 0078","desc":"昭和１０年東京井の頭に香道家吉田露香邸として創建。入母屋造，桟瓦葺，木造２階建の主屋（広間茶室）と，松永安左衛門命名の３畳台目席「而生庵」から成る。数寄屋建築の大家である仰木魯堂の設計になる数少ない現存作品のひとつとして貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002213"},{"id":"00005749","register_sub_id":"101","register_pk":"106737","name":"須藤家住宅奥座敷","kana":"すどうけじゅうたくおくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県桐生市堤町一丁目2325","lat":36.41837783,"lng":139.3274822,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積78㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"10 － 0197","desc":"敷地の西辺に近接して，主屋と棟を振って建つ木造２階建。寄宿舎として建設された。北側は居間，南側は廊下を介して主屋と接続する。１階は寝室と南北２箇所の浴室，２階は８畳室と６畳室の２室を配す。切妻造，桟瓦葺で，外壁は下見板張で，清楚な意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005749"},{"id":"00005750","register_sub_id":"101","register_pk":"106738","name":"須藤家住宅主屋","kana":"すどうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県桐生市堤町一丁目2325","lat":36.418297,"lng":139.32756,"geo_status":"db","era":"明治前期／明治後期・大正期増改造","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積241㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"10 － 0196","desc":"元織物工場の事務所兼住宅。南側は工場を改装した木造２階建，切妻造の洋館で，下見板張外壁に上げ下げ窓を開く。内部は吹き抜けで，畳敷のギャラリーを巡らす。洋館の北に接続する木造２階建の和館は洋風小屋組である。玄関は大オーダーの円柱と円窓で飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005750"},{"id":"00005745","register_sub_id":"101","register_pk":"106733","name":"須藤家住宅土蔵","kana":"すどうけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県桐生市堤町一丁目2325","lat":36.418446,"lng":139.327637,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"10 － 0198","desc":"主屋の北に接続する土蔵造２階建で，切妻造，桟瓦葺。桁行３間，梁間２間の東西棟である。南面に戸口を開き，主屋との間に蔵前を設ける。小屋組はキングポストトラス。外壁は白漆喰塗で，腰を花崗岩の切石積とし，東面１階，２階に観音開きの塗戸付窓を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005745"},{"id":"00005754","register_sub_id":"101","register_pk":"106742","name":"曽我家住宅稲荷社","kana":"そがけじゅうたくいなりしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"群馬県","address":"群馬県桐生市本町1-7-7","lat":36.41839909,"lng":139.34381081,"geo_status":"db","era":"慶応3","year":1867,"year_source":"db","year_min":1867,"year_max":1867,"year_label":null,"structure":"木造平屋建、板葺、建築面積1.6㎡、覆屋付","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"10 － 0194","desc":"主屋の南，表門を入った正面にある屋敷社である。東を正面とした木造の一間社流造で，二軒繁垂木。屋根は板葺，浜床を設ける。向拝虹梁上に龍，頭貫木鼻に獅子の精緻な彫物を飾る。覆屋は正面入母屋造，背面切妻造の鉄板葺で，両開きの格子戸を吊り込む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005754"},{"id":"00005751","register_sub_id":"101","register_pk":"106739","name":"曽我家住宅主屋","kana":"そがけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県桐生市本町1-7-7","lat":36.4184,"lng":139.34391868,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積127㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"10 － 0191","desc":"街路に接して建つ木造平屋建の町家で，方４間の店の奥に中庭を介して座敷が続く。屋根は切妻造，桟瓦葺で，東側を寄棟造とする。北面は白漆喰塗とする。店は街路に面する東側に格子窓を設け，南側下屋に玄関を開く。一般の町家と異なった意匠で正面を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005751"},{"id":"00005753","register_sub_id":"101","register_pk":"106741","name":"曽我家住宅新座敷","kana":"そがけじゅうたくしんざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県桐生市本町1-7-7","lat":36.4185655,"lng":139.34365772,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造及び煉瓦造2階建、瓦葺、建築面積37㎡","structure_material":"木造及び煉瓦造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"10 － 0193","desc":"敷地の北辺，土蔵の西に東西棟で建つ。木造２階建で，桁行３間半，梁間３間の規模。屋根は切妻造の桟瓦葺とする。防火のため，路地に面した北側外壁は煉瓦壁とし，小窓を開く。２階は７畳半２室とし，南面に廊下が付く。敷地北側の防火性能を高めた構造をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005753"},{"id":"00005752","register_sub_id":"101","register_pk":"106740","name":"曽我家住宅土蔵","kana":"そがけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県桐生市本町1-7-7","lat":36.41853386,"lng":139.34373391,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積51㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"10 － 0192","desc":"敷地の北辺，主屋の西に東西棟で建つ。土蔵造２階建で，桁行６間，梁間２間半の規模である。主屋の西側縁を蔵前とする。１階を２室，２階は１室とする。屋根は切妻造の桟瓦葺で，外壁を白漆喰塗とし，２階南面に２箇所の窓を開く。敷地北側の防火性能を強化する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005752"},{"id":"00005755","register_sub_id":"101","register_pk":"106743","name":"曽我家住宅門","kana":"そがけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市本町1-7-7","lat":36.41832159,"lng":139.34392722,"geo_status":"db","era":"大正11頃","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"石造、間口3.3m","structure_material":"石造","registered":"2006.10.18(平成18.10.18)","register_no":"10 － 0195","desc":"街路に面した敷地東面の中央に開く表門。花崗岩の門柱一対が立つ。台石上に立つ１尺×８寸の角柱で，高さ約８尺。表面は瘤出し仕上げで，角は江戸切り状に仕上げる。門柱上に唐破風形の鉄パイプ製飾りを掛け渡し，中央に照明器具を吊り，渦形飾りをつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005755"},{"id":"00006786","register_sub_id":"101","register_pk":"107768","name":"高草木家住宅稲荷社","kana":"たかくさきけじゅうたくいなりしゃ","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"群馬県","address":"群馬県みどり市東町花輪92-1","lat":36.51926154,"lng":139.30715374,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石祠6基 石造、面積1.5㎡","structure_material":"石祠6基 石造","registered":"2008.03.07(平成20.03.07)","register_no":"10 － 0256","desc":"主屋の後方、敷地の北辺中央に位置する。基壇は幅２．３ｍ、奥行０．６７ｍ、高さ０．５９ｍで切石の２段積とし、安山岩製の小祠６基を並列する。小祠はそれぞれ、方形の基壇石、戸口を彫り込んだ石室、流造形の屋根石の３石からなる。素朴な造形を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006786"},{"id":"00006785","register_sub_id":"101","register_pk":"107767","name":"高草木家住宅主屋","kana":"たかくさきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県みどり市東町花輪92-1","lat":36.5191841,"lng":139.30725973,"geo_status":"db","era":"天保11／大正初期増築","year":1840,"year_source":"db","year_min":1840,"year_max":1840,"year_label":null,"structure":"木造2階建、瓦葺、建築面積210㎡","structure_material":"木造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"10 － 0255","desc":"銅山街道花輪宿の銅問屋。旧街道北側の敷地中央に南面して建つ、木造２階建である。桁行１０間梁間６間半規模で、切妻造桟瓦葺とする。東を土間、西を居室とし、南面に式台を構える。２階は蚕室に転用され、換気の越屋根を設ける。名主も勤めた旧家の遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006785"},{"id":"00014320","register_sub_id":"101","register_pk":"511309","name":"田島新一家住宅主屋","kana":"たじましんいちけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県伊勢崎市境島村字新地2158","lat":36.24620833,"lng":139.23763611,"geo_status":"db","era":"文久元年（1861）頃／明治5年頃増築・同中期・大正後期改修","year":1861,"year_source":"db","year_min":1861,"year_max":1861,"year_label":null,"structure":"木造2階建、瓦葺、建物面積192㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"10 - 0351","desc":"史跡田島弥平旧宅の近隣に建つ養蚕農家で、栄盛館の屋号で蚕種業を営んだ。総二階建、切妻造桟瓦葺で越屋根を三箇所設け、二階を蚕室とする。一階は広い土間と整形の床上部で、床構え付座敷を設ける。いわゆる三ツ櫓の建物で、総櫓が成立する以前の遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014320"},{"id":"00013686","register_sub_id":"101","register_pk":"505197","name":"田島善一家住宅主屋","kana":"たじまぜんいちけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県伊勢崎市境島村字新地2209","lat":36.24650833,"lng":139.23808056,"geo_status":"db","era":"江戸末期／明治41年移築増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積294㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"10 － 348","desc":"田島弥平旧宅（国史跡）の近隣に建つ蚕種を製造した民家。桁行一三間、梁間五間の総二階建部分を主体として、背面と東側面に下屋が付属する。屋根は入母屋造桟瓦葺で、棟全長に越屋根を掲げる。大規模ゆえの迫力を持つ建物で、島村の蚕種製造の興隆を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013686"},{"id":"00013687","register_sub_id":"101","register_pk":"505199","name":"田島達行家住宅主屋","kana":"たじまたつゆきけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県伊勢崎市境島村字新地2247他","lat":36.24585833,"lng":139.23954444,"geo_status":"db","era":"慶応2年(1866)／明治頃・大正頃・昭和3年・昭和46年増築","year":1866,"year_source":"db","year_min":1866,"year_max":1866,"year_label":null,"structure":"木造2階建、瓦葺、建築面積254㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"10 － 349","desc":"田島弥平旧宅（国史跡）の近隣に建つ。主体部は桁行九間梁間五間の切妻造桟瓦葺の総二階建で、二階を蚕室とし棟全長に越屋根を備える。周囲に積極的に増築し、背面東端に顕微鏡室を張出す。蚕種を製造した民家の近代における増築による規模拡大の一例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013687"},{"id":"00004924","register_sub_id":"101","register_pk":"105914","name":"寺内家住宅旧別荘","kana":"てらうちけじゅうたくきゅうべっそう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県桐生市宮本町3-7-15","lat":36.4200471,"lng":139.33870707,"geo_status":"db","era":"昭和12頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、瓦葺、建築面積153㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"10 － 0127","desc":"木造２階建，東西棟の入母屋造，桟瓦葺で，外壁を漆喰塗と下見板張で仕上げる。和式を基調とするが，１階に洋室の食堂を設け，２階東面にはスクラッチタイル張のバルコニーを設ける。昭和初期の郊外住宅地に建設された和洋折衷型の形式をもち貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004924"},{"id":"00004927","register_sub_id":"101","register_pk":"105917","name":"寺内家住宅主屋","kana":"てらうちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市永楽町6-7","lat":36.41247031,"lng":139.33689734,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺及び鉄板葺、建築面積148㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"10 － 0130","desc":"敷地北西に，蔵及び検反場の西面に隣接して建つ。入母屋造，桟瓦葺，東西棟の木造２階建。外壁は下見板張とし，全体を和風でまとめるが，スチーム暖房を採用し，玄関脇に洋間応接室を設け，中廊下式の居室配置とするなど，昭和初期の近代和風住宅の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004927"},{"id":"00004937","register_sub_id":"101","register_pk":"105927","name":"中村家住宅奥座敷","kana":"なかむらけじゅうたくおくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県桐生市本町1-6-33","lat":36.4188959,"lng":139.34482442,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積85㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"10 － 0140","desc":"文庫蔵の東に隣接して建つ。桁行１２メートル，梁間７．６メートル，木造平屋建で，東西棟の片寄棟造桟瓦葺になる。１０畳の主座敷及び６畳の次の間，土蔵，蔵前から成り，一つの小屋構造に土蔵を一体的に取り込んでいるのが特徴である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004937"},{"id":"00004939","register_sub_id":"101","register_pk":"105929","name":"中村家住宅門","kana":"なかむらけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市本町1-6-33","lat":36.41895704,"lng":139.34453911,"geo_status":"db","era":"昭和12頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造、瓦葺、間口2.3m","structure_material":"木造","registered":"2005.11.10(平成17.11.10)","register_no":"10 － 0142","desc":"店舗の南側，本町通に西面して建つ。間口２．３メートル，切妻屋根桟瓦葺で，扉は引違戸とする。外壁は店舗正面と同様，鼠漆喰塗とし，腰より下を石で飾る。店舗と並び，歴史的景観を形成すると共に，敷地南に通路を設ける桐生の近代町家の屋敷割を良く表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004939"},{"id":"00004938","register_sub_id":"101","register_pk":"105928","name":"中村家住宅浴場","kana":"なかむらけじゅうたくよくじょう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県桐生市本町1-6-33","lat":36.41890231,"lng":139.34469217,"geo_status":"db","era":"昭和12頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積6.2㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"10 － 0141","desc":"敷地の南辺に沿い，石蔵の西面に接して建つ。桁行２．９メートル，梁間２．３メートルの小規模な木造平屋建で，東西棟の桟瓦葺屋根がかかる。内部は浴室，脱衣所，釜場に分かれる。石蔵と一体的な外観を有し，屋敷構に欠くことのできない要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004938"},{"id":"00004936","register_sub_id":"101","register_pk":"105926","name":"中村弥市商店石蔵","kana":"なかむらやいちしょうてんいしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市本町1-6-33","lat":36.41885552,"lng":139.34479911,"geo_status":"db","era":"昭和12頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積25㎡","structure_material":"石造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"10 － 0139","desc":"敷地の南辺に沿って建つ。桁行１０．６メートル，梁間２．６メートル，安山岩の切石積からなる石造平屋建である。壁体に直接小屋をかけ，切妻造桟瓦葺の屋根を東西棟にかける。外壁は漆喰塗とし，腰壁は石を表す。屋敷内の景観を特徴づける要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004936"},{"id":"00004935","register_sub_id":"101","register_pk":"105925","name":"中村弥市商店新座敷","kana":"なかむらやいちしょうてんしんざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県桐生市本町1-6-33","lat":36.41889204,"lng":139.34475866,"geo_status":"db","era":"昭和12頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造平屋及び木造2階建、瓦葺、建築面積37㎡","structure_material":"鉄筋コンクリート造平屋及び木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"10 － 0138","desc":"鉄筋コンクリート造平屋建になる文庫蔵の蔵前座敷と，その西側に付属する切妻屋根桟瓦葺，木造２階建からなり，新座敷と呼ばれる。鉄筋コンクリート造部分は陸屋根でベランダとなる。文庫蔵と共に，住宅に鉄筋コンクリートが用いられた比較的早期の事例になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004935"},{"id":"00004934","register_sub_id":"101","register_pk":"105924","name":"中村弥市商店文庫蔵","kana":"なかむらやいちしょうてんぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市本町1-6-33","lat":36.41895769,"lng":139.34473407,"geo_status":"db","era":"昭和12頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積23㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"10 － 0137","desc":"奥座敷と新座敷に接して建つ。鉄筋コンクリート造２階建，東西棟の切妻造桟瓦葺で，南側平壁に入口を設け，北側平壁は路地に面する。外壁はペイントを塗り白漆喰塗土蔵のように見せる。昭和初期の鉄筋コンクリート造の蔵として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004934"},{"id":"00011872","register_sub_id":"101","register_pk":"211051","name":"野口家住宅主屋","kana":"のぐちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県みどり市大間々町大間々1331","lat":36.435681,"lng":139.275232,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積140㎡、門付","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"10-339","desc":"街路に西面して建つ材木商の店舗兼住宅。明治六年からは酒造業も営んでいた。街路に面して平入とする南北棟、土蔵造のミセ部分と、背面にやや斜めに続く東西棟、木造の居室部分からなり、南列を土間とする。大間々の往時の景観を今に伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011872"},{"id":"00001326","register_sub_id":"101","register_pk":"102316","name":"萩原家住宅旧繭蔵","kana":"はぎわらけじゅうたくきゅうまゆぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県前橋市朝日町1-27-9","lat":36.38887431,"lng":139.08421371,"geo_status":"db","era":"昭和10代","year":1935,"year_source":"converted","year_min":1935,"year_max":1935,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"10 － 0040","desc":"製糸に用いる繭を納めた倉庫で，主屋・座敷の北東に建つ。比較的に規模の大きな土蔵で，良質の材を用いた丁寧なつくりになる。付近一帯は製糸業で栄えたが，現在製糸関連の建物はほとんど失われており，地域一帯の歴史を物語る上で貴重な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001326"},{"id":"00006081","register_sub_id":"101","register_pk":"107066","name":"荻原家住宅主屋","kana":"はぎわらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県桐生市新宿2-9-7","lat":36.399136,"lng":139.337479,"geo_status":"db","era":"明治10","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積59㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"10 － 0229","desc":"桐生市街中心の新宿通りに東面して敷地を構える。敷地中央に建つ木造平屋建で，切妻造の玄関部と片流れ屋根の座敷部が矩折れに接続する。玄関部は取次の間２畳と８畳間，座敷棟は蔵前座敷と奥座敷の６畳２室からなる。造作は丁寧で良好に維持されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006081"},{"id":"00001325","register_sub_id":"101","register_pk":"102315","name":"萩原家住宅主屋座敷","kana":"はぎわらけじゅうたくしゅおくざしき","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県前橋市朝日町1-27-9","lat":36.388699,"lng":139.084061,"geo_status":"db","era":"昭和10代","year":1935,"year_source":"converted","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積88㎡","structure_material":"木造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"10 － 0039","desc":"萩原家は製糸業を営み栄えた家で，主屋及び座敷は屋敷地の正面中央に建つ。現在失われているが，その背後には工場が並んでいた。木造平屋建，瓦葺の小規模な建物であるが，西南隅に接客用の洋間をもつ質の高いつくりで，時代の流行をよく示す住宅建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001325"},{"id":"00006146","register_sub_id":"101","register_pk":"107130","name":"荻原家住宅土蔵","kana":"はぎわらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県桐生市新宿2-9-7","lat":36.39917504,"lng":139.33745089,"geo_status":"db","era":"明治10","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"10 － 0230","desc":"主屋座敷部の北に接して建つ。土蔵造２階建の東西棟で，桁行４間，梁間２間半，切妻造，桟瓦葺とする。外壁は白漆喰塗で，腰は鉄板で覆う。１階南面東寄りに戸口を設け，主屋の蔵前座敷に両開塗戸を開く。西妻面の１・２階の窓が景観のアクセントとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006146"},{"id":"00006147","register_sub_id":"101","register_pk":"107131","name":"荻原家住宅門及び塀","kana":"はぎわらけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県桐生市新宿2-9-7","lat":36.39906816,"lng":139.33753117,"geo_status":"db","era":"明治10","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"門 木造、瓦葺、間口3.4m、潜戸付、塀 木造、瓦葺、延長19m","structure_material":"門 木造","registered":"2007.05.15(平成19.05.15)","register_no":"10 － 0231","desc":"敷地南側の小路に面して開く門。間口３．４ｍの棟門で，切妻造，桟瓦葺とする。門口は幅１．７ｍで，両開板扉を吊り込み，東に潜戸を開く。敷地南辺を画す塀は門の西から延長１９ｍあり，白漆喰塗とし，腰を簓子下見板張とする。敷地南側の景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006147"},{"id":"00000756","register_sub_id":"101","register_pk":"101746","name":"平形家住宅門屋（旧中山郵便局）","kana":"ひらかたけじゅうたくもんや（きゅうなかやまゆうびんきょく）","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県吾妻郡高山村中山103-1","lat":36.62899694,"lng":138.95672434,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造２階建，鉄板葺，建築面積158㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"10 － 0029","desc":"平形家は三国街道中山宿の本陣で，江戸末期に建てられた門屋は街道に面して建つ。外観は伝統的な町屋に似るが，一部を明治６年に郵便局舎としたもので，山間の地に開設された初期の郵便局舎の様子を示す類例の少ない事例として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000756"},{"id":"00005788","register_sub_id":"101","register_pk":"106776","name":"平田家住宅主屋","kana":"ひらたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市本町1-6-28","lat":36.41855309,"lng":139.34443084,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積112㎡、渡廊下付","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"10 － 0201","desc":"敷地の中央に位置し，店舗の背面から渡廊下で接続する平屋建。桁行６間，梁間３間半で，表裏に庇をつけて縁とする。背後に水屋と便所が突出する。内部は整形四間取で，北東に床棚付の８畳座敷を置く。外壁は押縁下見板張で，伸びやかな切妻屋根が目をひく。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005788"},{"id":"00005823","register_sub_id":"101","register_pk":"106809","name":"平田家住宅土蔵","kana":"ひらたけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市本町1-6-28","lat":36.41850486,"lng":139.34459595,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"10 － 0202","desc":"敷地の東端に位置する東西棟の土蔵造２階建である。桁行４間，梁間２間半の切妻造，桟瓦葺で，南面に瓦葺庇をつけて戸口を設け，両開塗戸を吊り込む。店蔵よりやや簡素なつくりだが，外壁は白漆喰塗で北面には押縁下見板を張り，敷地後方で存在感を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005823"},{"id":"00001327","register_sub_id":"101","register_pk":"102317","name":"広瀬川美術館（旧近藤嘉男アトリエ及び絵画教室ラ・ボンヌ）","kana":"ひろせがわびじゅつかん（きゅうこんどうよしおあとりえおよびかいがきょうしつら・ぼんぬ）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"群馬県","address":"群馬県前橋市千代田町3-3-10","lat":36.39509277,"lng":139.06890041,"geo_status":"db","era":"昭和23","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積100㎡","structure_material":"木造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"10 － 0041","desc":"画家のアトリエ兼住宅をそのまま保存して美術館とした建物。外観はインターナショナルスタイルを意識した形で，正面の大きな窓にアトリエらしい工夫がうかがえる。１階を利用して絵画教室を開いていた時期もあり，近隣の人々に広く親しまれている建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001327"},{"id":"00006151","register_sub_id":"101","register_pk":"107135","name":"藤生家住宅稲荷社覆屋","kana":"ふじうけじゅうたくいなりしゃおおいや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県桐生市広沢町5-1179","lat":36.381947,"lng":139.344864,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、鉄板葺、建築面積1.9㎡、稲荷社及び石宮2基付","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"10 － 0223","desc":"敷地北半部のほぼ中央に位置する木造平屋建。丸石積の基壇の上に建つ間口３尺５寸の方１間の建物で，向拝柱を立てて流造の屋根を架け鉄板葺とする。内部は板床を張り，江戸期製作と推定される稲荷社を祀る。外壁は真壁造白漆喰塗で，正面に両開板扉を吊り込む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006151"},{"id":"00006110","register_sub_id":"101","register_pk":"107094","name":"藤生家住宅隠居屋","kana":"ふじうけじゅうたくいんきょや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県桐生市広沢町5-1179","lat":36.381714,"lng":139.344818,"geo_status":"db","era":"明治前期／明治後期増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積93㎡","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"10 － 0213","desc":"主屋の西の縁から坪庭を介して接続する木造２階建，寄棟造，桟瓦葺である。１階は８畳座敷と６畳２室で，南に縁を付け，２階は１４畳大の広間に床を構え，南に縁を設ける。西に風呂棟，西北に便所棟を突出する。主屋と趣を異にし，敷地景観に変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006110"},{"id":"00006126","register_sub_id":"101","register_pk":"107110","name":"藤生家住宅内蔵","kana":"ふじうけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県桐生市広沢町5-1179","lat":36.381844,"lng":139.344879,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建及び木造平屋建、瓦葺、建築面積56㎡","structure_material":"土蔵造2階建及び木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"10 － 0215","desc":"主屋の北面西端から，蔵前座敷を介して接続する土蔵造２階建である。桁行３間，梁間２間規模で，南面に戸口を設け，１・２階の西面に両開塗戸付の窓を開く。外壁は白漆喰塗で腰を下見板張とする。蔵前座敷は木造平屋建で１０畳に床を構え，西に縁が付く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006126"},{"id":"00006155","register_sub_id":"101","register_pk":"107139","name":"藤生家住宅表門","kana":"ふじうけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県桐生市広沢町5-1179","lat":36.381615,"lng":139.34523,"geo_status":"db","era":"明治前期／昭和48曳家","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、間口5.8m","structure_material":"木造","registered":"2007.05.15(平成19.05.15)","register_no":"10 － 0224","desc":"敷地南辺の中央に位置する。間口５．８ｍの腕木門で，屋根は切妻造，桟瓦葺とする。門口は幅２．５ｍで，板戸を引分けとする。両脇間は真壁造の白漆喰塗で，腰を下見板張としている。南面道路の拡幅で現位置に移設した。敷地正面に風格を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006155"},{"id":"00006087","register_sub_id":"101","register_pk":"107072","name":"藤生家住宅主屋","kana":"ふじうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県桐生市広沢町5-1179","lat":36.38178988,"lng":139.34503212,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺（銅板仮葺）、建築面積163㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"10 － 0212","desc":"桐生市街の南，広沢川右岸に敷地を構える上層農家住宅である。敷地中央に南面して建つ。桁行１１間規模の木造平屋建で，入母屋造の茅葺（銅板仮葺）とする。西半の床上は８畳座敷をもつ整形四間取とし，南と西に瓦庇を付けて縁とする。落ち着いた佇まいを呈す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006087"},{"id":"00006148","register_sub_id":"101","register_pk":"107132","name":"藤生家住宅水車小屋及び物置","kana":"ふじうけじゅうたくすいしゃごやおよびものおき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県桐生市広沢町5-1179","lat":36.381973,"lng":139.34518995,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"10 － 0219","desc":"敷地東辺の中央に位置する。木造平屋建で，２間四方の水車小屋の北に，桁行４間，梁間１間の物置が並び建ち，一連の瓦葺屋根を架ける。外壁は真壁造中塗仕上げで，東面は南に連なる外塀と共に縦羽目板張とする。かつては敷地東の水路を利用して水車を回した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006148"},{"id":"00006156","register_sub_id":"101","register_pk":"107140","name":"藤生家住宅外塀","kana":"ふじうけじゅうたくそとべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県桐生市広沢町5-1179","lat":36.38173343,"lng":139.34469403,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、総延長24m","structure_material":"木造","registered":"2007.05.15(平成19.05.15)","register_no":"10 － 0226","desc":"敷地の外周を画す塀で，敷地東面の水車小屋から南へ７．５ｍ，敷地西面中央部に延長１６ｍが残る。玉石積の石垣に切石を据えて土台を置く。高さ２．５ｍで，外側は縦羽目板張，内側は中塗仕上げで瓦屋根を載せる。良好に維持され，引き締まった外観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006156"},{"id":"00006111","register_sub_id":"101","register_pk":"107095","name":"藤生家住宅茶室","kana":"ふじうけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県桐生市広沢町5-1179","lat":36.381874,"lng":139.344772,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"10 － 0214","desc":"内蔵の北西に位置する木造平屋建で，茶室は４畳半で床棚を構えた書院式とする。南面から西面へ濡縁が付く。東面は鉄板葺下屋を付けて縁とし，北に便所が突出する。屋根は寄棟造，桟瓦葺で，外壁は真壁造の中塗仕上げとする。敷地北西の庭園景観の主要素となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006111"},{"id":"00006157","register_sub_id":"101","register_pk":"107141","name":"藤生家住宅中門","kana":"ふじうけじゅうたくちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県桐生市広沢町5-1179","lat":36.381657,"lng":139.344986,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口1.8m、塀延長10m付","structure_material":"木造","registered":"2007.05.15(平成19.05.15)","register_no":"10 － 0225","desc":"隠居屋の前庭を画す塀に開く門。間口１間の腕木門で，切妻造，桟瓦葺。格子戸を引違いに建て込む。塀は隠居屋の南面東端から折曲り，延長１０ｍ。東面は白漆喰塗で腰を下見板張，西面は中門以北を中塗仕上げ，以南を縦板張とし，内外の意匠に変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006157"},{"id":"00006125","register_sub_id":"101","register_pk":"107109","name":"藤生家住宅土蔵","kana":"ふじうけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県桐生市広沢町5-1179","lat":36.381744,"lng":139.345337,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"10 － 0216","desc":"主屋の南東方に建つ土蔵造２階建の什器蔵。桁行４間，梁間２間半の南北棟で，切妻造の置屋根を桟瓦葺とする。西面の桁行全長に瓦葺庇を付けて戸口を開き，引戸を建て込む。外壁は白漆喰塗で，２階の東面と南面に窓を設ける。敷地南東からの景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006125"},{"id":"00006159","register_sub_id":"101","register_pk":"107143","name":"藤生家住宅西井戸","kana":"ふじうけじゅうたくにしいど","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県桐生市広沢町5-1179","lat":36.381828,"lng":139.344803,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"石造、面積0.80㎡","structure_material":"石造","registered":"2007.05.15(平成19.05.15)","register_no":"10 － 0228","desc":"内蔵の西方，庭園池水の傍らに位置する石組の井戸。井戸枠は９０ｃｍ四方で，高さ２０ｃｍ余，厚さ１２ｃｍの凝灰岩切石４枚を相欠きで精緻に組み合わせ，厚さ１７ｃｍの板石上に据える。井筒下方は玉石の空積で，深さ３．６ｍを計る。茶室用の井戸と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006159"},{"id":"00006158","register_sub_id":"101","register_pk":"107142","name":"藤生家住宅東井戸","kana":"ふじうけじゅうたくひがしいど","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県桐生市広沢町5-1179","lat":36.381908,"lng":139.345016,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"石造、面積1.1㎡","structure_material":"石造","registered":"2007.05.15(平成19.05.15)","register_no":"10 － 0227","desc":"主屋の北背後，味噌蔵の南方に位置する石組の井戸である。井戸枠は１ｍ四方で，高さ４５ｃｍ，厚さ１５ｃｍの花崗岩の切石４枚を相欠きで精緻に組み合わす。井筒下方は玉石の空積で，深さは４．３ｍとする。飲料水に使われた井戸で，石工技術に優れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006158"},{"id":"00006150","register_sub_id":"101","register_pk":"107134","name":"藤生家住宅盆栽小屋","kana":"ふじうけじゅうたくぼんさいごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県桐生市広沢町5-1179","lat":36.38217395,"lng":139.34500261,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、鉄板葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"10 － 0220","desc":"敷地東辺の北端に位置する南北棟の木造平屋建である。桁行４間，梁間１間で，切妻造，鉄板葺とする。外壁は縦板張で内壁は真壁造の中塗仕上げである。西面は１間毎に柱を立て，引違戸を入れる。鉢物の越冬に用いた建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006150"},{"id":"00006149","register_sub_id":"101","register_pk":"107133","name":"藤生家住宅薪小屋","kana":"ふじうけじゅうたくまきごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県桐生市広沢町5-1179","lat":36.382156,"lng":139.344894,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、鉄板葺、建築面積38㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"10 － 0221","desc":"敷地の北辺東寄りに位置する東西棟の木造平屋建である。桁行４間半，梁間２間半で，切妻造，鉄板葺とする。切石の基礎の上に建ち，真壁造で外壁は鉄板で覆う。南面中央東寄りに出入口を設け，片開板扉を吊り込む。薪炭を保存した建物として使われてきた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006149"},{"id":"00006127","register_sub_id":"101","register_pk":"107111","name":"藤生家住宅味噌蔵","kana":"ふじうけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県桐生市広沢町5-1179","lat":36.381947,"lng":139.344971,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋建、瓦葺、建築面積12㎡","structure_material":"土蔵造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"10 － 0217","desc":"主屋北背後，東寄りに建つ東西棟の土蔵造平屋建。桁行２間半，梁間１間半で，切妻造の置屋根を桟瓦葺とする。基礎を玉石積とし，外壁は白漆喰塗で，腰を押縁下見板張とする。南面中央東寄りに戸口を設け，引戸を建て込む。敷地背面側の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006127"},{"id":"00006141","register_sub_id":"101","register_pk":"107125","name":"藤生家住宅物置","kana":"ふじうけじゅうたくものおき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県桐生市広沢町5-1179","lat":36.381577,"lng":139.345123,"geo_status":"db","era":"明治前期／昭和48曳家","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"10 － 0218","desc":"敷地の南辺西寄り，水路護岸を兼ねる玉石積基礎の上に建つ。東西棟の木造平屋建である。桁行７間，梁間２間半で，屋根は切妻造，桟瓦葺で、和小屋とする。外壁は真壁造，白漆喰塗で，腰を押縁下見板張，東妻は全面下見板張とする。敷地南面の重厚な構えをなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006141"},{"id":"00006140","register_sub_id":"101","register_pk":"107124","name":"藤生家住宅浴室","kana":"ふじうけじゅうたくよくしつ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県桐生市広沢町5-1179","lat":36.38190202,"lng":139.34493393,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積5.0㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"10 － 0222","desc":"主屋の背後，内蔵と味噌蔵の間に位置する木造平屋建の東西棟である。桁行１間半，梁間１間で，屋根は切妻造，桟瓦葺とする。腰まで凝灰岩の切石積とし，外壁を縦羽目板張とする。浴槽は五右衛門風呂で，外側をタイル貼とする。戸口と窓はガラス障子とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006140"},{"id":"00002012","register_sub_id":"101","register_pk":"103002","name":"堀口家住宅北蔵","kana":"ほりぐちけじゅうたくきたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県渋川市上ノ町2335","lat":36.495655,"lng":139.0000506,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"10 － 0054","desc":"主屋の南方，敷地の中央北寄りに南蔵と並んで建つ。店蔵・主屋とは棟を直交した切妻造，桟瓦葺，妻入の２階建土蔵で，北面と西面に下屋を差し掛け，主屋側の北面に入口を設ける。内部は階下の床を張らず土間とする。腰を海鼠壁とするなど丁寧な造りの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002012"},{"id":"00002011","register_sub_id":"101","register_pk":"103001","name":"堀口家住宅主屋","kana":"ほりぐちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県渋川市上ノ町2335","lat":36.4958,"lng":139.000061,"geo_status":"db","era":"慶応2頃","year":1866,"year_source":"db","year_min":1866,"year_max":1866,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積70㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"10 － 0053","desc":"店蔵の背後，南側に店蔵と棟を平行にして建つ。木造２階建，切妻造，もと板葺（現在は鉄板葺），平入の住居部で，店蔵から見て右側の西方をカミテとし，東方のシモテは当初は通り庭としていた。改造はあるが，当地方における商家の住居部型式を伝え貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002011"},{"id":"00002013","register_sub_id":"101","register_pk":"103003","name":"堀口家住宅南蔵","kana":"ほりぐちけじゅうたくみなみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県渋川市上ノ町2336","lat":36.49553027,"lng":139.00002316,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積48㎡","structure_material":"土蔵造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"10 － 0055","desc":"敷地のほぼ中央，西寄りの位置に北蔵と並んで建つ。北蔵より長い桁行６間，梁間２間半規模の，切妻造，桟瓦葺，平入の白漆喰塗土蔵で，西面に下屋を差し掛けて蔵前をつくる。北蔵と同様に内部を叩き土間とし，腰を海鼠壁とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002013"},{"id":"00013948","register_sub_id":"101","register_pk":"508208","name":"町田清家住宅主屋","kana":"まちだきよしけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県伊勢崎市境島村字立作3143他","lat":36.24593889,"lng":139.26063611,"geo_status":"db","era":"明治20年頃／同27年頃改修","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、瓦葺、建築面積122㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"10 - 0350","desc":"島村南東部に位置。二階建切妻造桟瓦葺、南面する農家主屋の床上部（土間部は建替）。西と北に下屋を付す。田の字形平面で表座敷とし、北下屋に二室配置。二階は出桁で開口を掃出とし、かつて手摺を付した。明治中期の特徴を持ち、蚕種製造民家の変遷を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013948"},{"id":"00002215","register_sub_id":"101","register_pk":"103205","name":"町田家住宅主屋","kana":"まちだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県吾妻郡中之条町大字中之条982","lat":36.5887673,"lng":138.84500452,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、鉄板葺、建築面積266㎡","structure_material":"木造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"10 － 0080","desc":"大庄屋や区長を務めた家柄の役宅兼住宅。間口１２間，奥行１０間のＬ型平面をもつ大型町屋で，国道３５３号線沿いの南面の西寄りに大振りな起り破風の玄関構えをとる。一時郡役所が置かれたこともあり，明治前期郡役所建築の様子を知るうえでも貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002215"},{"id":"00002217","register_sub_id":"101","register_pk":"103207","name":"町田家住宅外蔵","kana":"まちだけじゅうたくそとぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県吾妻郡中之条町大字中之条982","lat":36.58881786,"lng":138.84522775,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"10 － 0082","desc":"味噌蔵の東北方に建つ。桁行６間，梁行３間規模の２階建白漆喰土蔵で，東西棟，切妻造，置屋根形式とし，西妻面に庇を差し出して蔵前を造る。腰や２階窓台位置に胴蛇腹風の帯を回し，軒蛇腹に眉をつけるなど丁寧な造作によって際だつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002217"},{"id":"00002219","register_sub_id":"101","register_pk":"103209","name":"町田家住宅塀","kana":"まちだけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県吾妻郡中之条町大字中之条982","lat":36.58913047,"lng":138.84515263,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造、延長83m","structure_material":"木造","registered":"2001.08.28(平成13.08.28)","register_no":"10 － 0084","desc":"主屋後方から西に矩折れになったＬ型の敷地の西辺と北辺を区切る塀。木造の屋根付板塀で，棟の下を透いた軽快な造りとし，西辺のほぼ中央に裏庭に通じる門１所を開ける。屋敷構えの境界を示すとともに，屋敷景観を整える役目を果たす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002219"},{"id":"00002216","register_sub_id":"101","register_pk":"103206","name":"町田家住宅味噌蔵","kana":"まちだけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県吾妻郡中之条町大字中之条982","lat":36.58882323,"lng":138.84513596,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"10 － 0081","desc":"主屋東北隅の北方に位置し，野面玉石乱積の石垣基壇上に建つ。桁行３間，梁行２間規模，南北棟，切妻造，置屋根形式の土蔵で，北妻面に１間幅の下屋を張り出して蔵前とする。腰を板張とした簡素な土蔵であるが，屋敷構えの主要構成要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002216"},{"id":"00002218","register_sub_id":"101","register_pk":"103208","name":"町田家住宅門","kana":"まちだけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県吾妻郡中之条町大字中之条982","lat":36.58865271,"lng":138.84502663,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造薬医門、間口2.4m","structure_material":"木造薬医門","registered":"2001.08.28(平成13.08.28)","register_no":"10 － 0083","desc":"間口１間半規模，１間１戸の切妻造，桟瓦葺の薬医門で，正面右手に屋根付板塀を従え，左手は主屋東妻側の野面玉石積石垣との間に通用口を設ける。名望家に相応しい門構えで，国道３５３号線に沿った正面側の屋根を段葺とする点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002218"},{"id":"00004799","register_sub_id":"101","register_pk":"105789","name":"森家住宅石蔵（旧穀蔵）","kana":"もりけじゅうたくいしぐら（きゅうこくぐら）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市本町1-3-9","lat":36.41971355,"lng":139.34483942,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積50㎡","structure_material":"石造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"10 － 0125","desc":"事務所から門を挟んで北に建つ。桁行５間，梁間３間規模の石造平屋建で，寄棟造，桟瓦葺である。もと穀蔵で，庭側に戸口があり，街路側の開口部は昭和３６年の改造である。外壁は腰に石積を見せて白漆喰塗とする。店蔵，事務所とともに独特の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004799"},{"id":"00005580","register_sub_id":"101","register_pk":"106568","name":"森島家住宅内塀","kana":"もりしまけじゅうたくうちべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市東4-2-24","lat":36.40980354,"lng":139.34485358,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造、瓦葺、延長19m","structure_material":"木造","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0186","desc":"主屋と門をつなぎ，玄関前の空間と主屋南側の庭を区分する塀を築く。木造，桟瓦葺，長さ１９ｍで，北端近くに潜戸を設ける。土台の上に柱を立て，壁を漆喰塗とし，１間おきに下地窓を開け，腰を竪板張とする。門から玄関に至る住居の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005580"},{"id":"00005576","register_sub_id":"101","register_pk":"106564","name":"森島家住宅主屋","kana":"もりしまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市東4-2-24","lat":36.4099739,"lng":139.34476228,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積502㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0182","desc":"敷地の南西に位置し，南側に庭をとって建つ。桁行１６．９ｍ，梁間９．５ｍ，木造平屋建，桟瓦葺，切妻造及び入母屋造とする。６間を２列に並べ，東側４間は作業場を兼ねる。玄関横に洋間応接室を置き，浴室を別棟で付属し，多様な外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005576"},{"id":"00005578","register_sub_id":"101","register_pk":"106566","name":"森島家住宅西蔵","kana":"もりしまけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県桐生市東4-2-24","lat":36.410027,"lng":139.344666,"geo_status":"db","era":"昭和26頃","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造3階建、瓦葺、建築面積26㎡","structure_material":"木造3階建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0184","desc":"主屋北側に東蔵と並んで建つ。桁行５．８ｍ，梁間４．４ｍの規模で，木造３階建，切妻造，桟瓦葺とし，外壁をモルタル塗とする。１，２階を内壁板張りの蔵として使うが，３階は８畳間の座敷とする。生糸の倉庫として建てられ，機業家住居の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005578"},{"id":"00005577","register_sub_id":"101","register_pk":"106565","name":"森島家住宅東蔵","kana":"もりしまけじゅうたくひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市東4-2-24","lat":36.41003,"lng":139.344727,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積21㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0183","desc":"主屋北側に建ち，主屋の一部を蔵前とし，内蔵の形式をとる。桁行５．６ｍ，梁間３．８ｍの規模で，木造２階建，切妻造，桟瓦葺とし，外壁は目地付きのモルタル塗洗い出し仕上げとする。内壁を板張りとし，反物の収蔵庫としても使われた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005577"},{"id":"00005579","register_sub_id":"101","register_pk":"106567","name":"森島家住宅門","kana":"もりしまけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市東4-2-24","lat":36.40971649,"lng":139.34486992,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造、瓦葺、間口2.7m、塀延長46m付","structure_material":"木造","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0185","desc":"敷地南辺のほぼ中央に門を開き，両側に袖塀を設ける。外塀は袖塀に続き，主屋南側の庭の北側と西側を囲むように延びる。北側の塀の壁を木造，桟瓦葺とし，西側をＲＣ造の壁とする。門は木造の棟門の形式で間口２．７ｍの規模で，切妻造，桟瓦葺とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005579"},{"id":"00001898","register_sub_id":"101","register_pk":"102888","name":"吉田家住宅和泉庄御殿","kana":"よしだけじゅうたくいずみしょうごてん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県高崎市大橋町36-9","lat":36.338707,"lng":138.999969,"geo_status":"db","era":"昭和2／平成2移築","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積63㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"10 － 0042","desc":"商家吉田家の接待用家屋を移築復原したもの。木造２階建，入母屋造桟瓦葺で，２階に出桁庇を付け，外壁を真壁漆喰塗とする。随所に銘木が用いられ，入念に施された螺鈿，漆塗，彫物等を見所とする。棟梁は新潟の石黒博司。高崎を代表する近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001898"},{"id":"00010921","register_sub_id":"101","register_pk":"208892","name":"秋田家住宅土蔵","kana":"あきたけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県所沢市寿町527","lat":35.791396,"lng":139.468031,"geo_status":"db","era":"明治15","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"11-0150","desc":"店舗兼主屋の北西側に一体化して建つ。土蔵造二階建、桁行九・一メートル梁間四・五メートル、切妻造桟瓦葺で、店舗と廊下側の戸口に、いずれも黒漆喰塗の重厚な扉を開き、二階窓の庇周りでは店舗同様に木部を銅板張とする。店舗と共に商家の構えを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010921"},{"id":"00010922","register_sub_id":"101","register_pk":"208893","name":"秋田家住宅離れ","kana":"あきたけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県所沢市寿町527","lat":35.791494,"lng":139.468047,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"11-0151","desc":"土蔵の北側に建つ桟瓦葺の平屋建で、八畳主室と次の間に縁を廻らせる。主室は座敷飾りを備え、クロガキの床柱など良材を用い、堅実な仕上げの書院とする。矩の手に廻る縁は、ガラス戸をたて、蜀江模様風の組子のガラス欄間を飾るなど、気品のある造作になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010922"},{"id":"00010923","register_sub_id":"101","register_pk":"208894","name":"秋田家住宅門及び塀","kana":"あきたけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県所沢市寿町527-2","lat":35.79148664,"lng":139.46809788,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"門 木造、瓦葺、間口1.6m 塀 木造、瓦葺、総延長9.7m","structure_material":"門 木造","registered":"2016.02.25(平成28.02.25)","register_no":"11-0152","desc":"離れの主座敷前に構える門と両側にのびる塀。門は一間腕木門、切妻造桟瓦葺で、内開きの桟唐戸に家紋と木瓜枠を飾る。塀は上部に格子窓を配して腰を簓子下見板張とし、北半は敷地形状に合わせて高低差をつくる。商家の後方敷地に落ち着いた佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010923"},{"id":"00003386","register_sub_id":"101","register_pk":"104376","name":"朝日屋原薬局東雲不動尊祠","kana":"あさひやはらやっきょくしののめふどうそんほこら","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"埼玉県","address":"埼玉県志木市本町二丁目1618","lat":35.83379642,"lng":139.57986334,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積0.95㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"11 － 0055","desc":"細長い屋敷地のほぼ中央，物置の東方にあり，不動尊を祀る。当時の生活文化の一端を示す施設。切石積基壇上に建ち，規模は桁行，梁間とも１間と小さく，切妻造，平入で，屋根鉄板葺である。木目をよく現した素木で，内法虹梁の絵様などに造形の冴えをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003386"},{"id":"00003381","register_sub_id":"101","register_pk":"104371","name":"朝日屋原薬局土蔵","kana":"あさひやはらやっきょくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県志木市本町二丁目1618","lat":35.8337948,"lng":139.57966931,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造2階建、瓦葺一部鉄板葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"11 － 0050","desc":"東西に細長い屋敷地のほぼ中央，主屋後方に建つ。木造２階建，東西棟の切妻造，桟瓦葺，平入で，南面に扉口をつけ，下屋庇を設ける。外壁は丁寧な白漆喰塗であるが，腰は煉瓦積とする。伝統工法に近代の意匠を取り込んだ当時の造形感覚を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003381"},{"id":"00003384","register_sub_id":"101","register_pk":"104374","name":"朝日屋原薬局離れ","kana":"あさひやはらやっきょくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県志木市本町二丁目1618","lat":35.83373379,"lng":139.58003366,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺一部鉄板葺、建築面積55㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"11 － 0053","desc":"東西に細長い屋敷地の東方に，南面して建つ。木造の総２階建，入母屋造，桟瓦葺で，階境に庇を廻し，１階南面東端に切妻造の玄関を設ける。各階を高くとり，開口部にはガラス窓を多用し，吹寄風で小舞打の軒廻りなど，数寄屋風の軽快な意匠が要所にみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003384"},{"id":"00003382","register_sub_id":"101","register_pk":"104372","name":"朝日屋原薬局物置","kana":"あさひやはらやっきょくものおき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"埼玉県","address":"埼玉県志木市本町二丁目1618","lat":35.83378842,"lng":139.5797929,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"11 － 0051","desc":"細長い屋敷地のほぼ中央，土蔵の東方に南を正面として建つ。真壁造で，平屋建（もと２階建），東西棟の切妻造，鉄板葺，平入とする。収納施設らしく長い柱を用いて内部空間を高くつくっている。商家の屋敷構成を把握する上で，欠かせない存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003382"},{"id":"00003385","register_sub_id":"101","register_pk":"104375","name":"朝日屋原薬局門及び塀","kana":"あさひやはらやっきょくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県志木市本町二丁目1618","lat":35.83373359,"lng":139.57942876,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造、銅板葺、間口1.8m、延長6.7m","structure_material":"木造","registered":"2003.07.01(平成15.07.01)","register_no":"11 － 0054","desc":"街道に面して建つ主屋の南側に連続し，屋敷正面の構えを整えている。主屋寄りに建つ門は，１間腕木門形式で，この左右に縦板張，目板打の塀が延びる。いずれも疎垂木の銅板葺屋根をかける。塀は連続して見えるが，両側とも北半分が引き込み戸になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003385"},{"id":"00003383","register_sub_id":"101","register_pk":"104373","name":"朝日屋原薬局洋館","kana":"あさひやはらやっきょくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県志木市本町二丁目1618","lat":35.83371866,"lng":139.57950924,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"11 － 0052","desc":"主屋の南側に建てられた小規模な洋風建築。木造平屋建，寄棟造，桟瓦葺で，西を正面として玄関ポーチを設ける。内部は１室で，東面に縁風の廊下を備える。外壁は漆喰塗だが，腰と開口部廻りは人造石洗い出し仕上げで飾り，瀟洒な外観に変化を持たせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003383"},{"id":"00005425","register_sub_id":"101","register_pk":"106413","name":"新井家住宅主屋","kana":"あらいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県春日部市倉常757-1","lat":36.02058562,"lng":139.78541225,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積163㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"11 － 0101","desc":"散居集落の形態を留めた農家の主屋で，屋敷林を北に背負って南面して建つ。桁行８間半，梁間５間規模，寄棟造，もと茅葺の木造２階建で，東方を土間，西方を床上部とする。２階は養蚕部屋である。強風にそなえ，正面の柱に建具留めの渡し棒を入れる金具を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005425"},{"id":"00012689","register_sub_id":"101","register_pk":"367592","name":"大泉家住宅洋館","kana":"おおいずみけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県川口市領家五丁目3900","lat":35.79010694,"lng":139.738535,"geo_status":"db","era":"昭和13年頃","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"石造2階建、銅板葺、建築面積209㎡","structure_material":"石造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"11 － 175","desc":"市南部の工場地帯にある実業家宅。大谷石の石造二階建、南面中央の玄関左脇に八角形平面の応接室を設ける。外観は装飾を控えつつ、内部はステンドグラスやアールデコ風の意匠で華やかにつくる。昭和初期洋館の好例を示す。類例の少ない石造住宅としても貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012689"},{"id":"00012690","register_sub_id":"101","register_pk":"367593","name":"大泉家住宅和館","kana":"おおいずみけじゅうたくわかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県川口市領家五丁目3900","lat":35.79010694,"lng":139.738535,"geo_status":"db","era":"昭和13年頃","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積157㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"11 － 176","desc":"洋館西側に建つ離座敷。木造平屋建、南北棟の寄棟造で、南面東端に入母屋造の玄関を構えて正面を整える。外壁は下見板張で小壁を漆喰塗とする。内部は三間続きの和室を設け、東側に一間幅の縁を通す。重厚な洋館と並立し、格式ある屋敷構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012690"},{"id":"00007187","register_sub_id":"101","register_pk":"108169","name":"大澤家住宅旧文庫蔵","kana":"おおさわけじゅうたくきゅうぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県行田市行田290-1","lat":36.138061,"lng":139.460663,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積42㎡","structure_material":"煉瓦造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"11 － 0120","desc":"中心市街地の通りに面して建つ。東西棟の切妻造桟瓦葺で、南面に出入口を設ける。建築面積４２㎡の２階建。内部は漆喰仕上げで、トラス組とし、開口部には鉄扉を吊る。イギリス積の煉瓦造で、補強のための鉄筋コンクリートの水平ラインが印象的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007187"},{"id":"00012497","register_sub_id":"101","register_pk":"367792","name":"大島家住宅主屋","kana":"おおしまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県北足立郡伊奈町大字小室字中荻11064","lat":35.988251,"lng":139.625809,"geo_status":"geocoded","era":"江戸末期／昭和34年・同63年・平成25年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（金属板仮葺）、建築面積242㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"11 － 0174","desc":"奥行の長い敷地中央に東面して建つ農家主屋。北半を占める広い土間は重厚な梁組を現す。床上部は四間取の裏に細長い室を配する平面で、県北中部に分布する民家形式を示す。前列上手室に床、下手室に間口いっぱいの神棚を設けるなど地方的特色と格式を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012497"},{"id":"00003840","register_sub_id":"101","register_pk":"104830","name":"大谷家住宅裏門及び塀","kana":"おおたにけじゅうたくうらもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県深谷市稲荷町2-3-39","lat":36.19491594,"lng":139.29156436,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造、瓦葺、間口2.5m、塀折れ曲り延長63m、木戸付","structure_material":"木造","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0077","desc":"裏門は敷地北辺の東寄りに建ち，塀が左右に連続して敷地の北と東を区画する。裏門は１間１戸高麗門形式で，一軒疎垂木，桟瓦葺である。塀は真壁造で，腰は内外とも簓子下見板張，桟瓦葺屋根をかける。大規模屋敷の後方空間を重厚にかたちづくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003840"},{"id":"00003841","register_sub_id":"101","register_pk":"104831","name":"大谷家住宅欅空庵","kana":"おおたにけじゅうたくこくうあん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"埼玉県","address":"埼玉県深谷市稲荷町2-4-23","lat":36.19514204,"lng":139.29140711,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積70㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0078","desc":"主屋のある敷地の北西約４０ｍの地にある離れで，大規模屋敷の生活様式の一端を示す施設。南北方向で棟違いの寄棟造，桟瓦葺，平屋建で，東面のほぼ中央に切妻造の玄関をつけ，南側には下屋庇を廻す。たちの高いつくりや簡明な意匠など，大正期の造形を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003841"},{"id":"00003842","register_sub_id":"101","register_pk":"104832","name":"大谷家住宅米蔵","kana":"おおたにけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県深谷市稲荷町2-4-34","lat":36.19532326,"lng":139.29103459,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積80㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0079","desc":"主屋のある敷地とは道路を挟んだ北側にある。南面した切妻造，平入で，鉄筋コンクリート造の２階建，屋根は桟瓦葺とする。外壁はモルタル塗りで目地をつけ，石造風にみせる。小屋組はキングポストトラスで桁・垂木を受けた木造で，当時の混構造を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003842"},{"id":"00003834","register_sub_id":"101","register_pk":"104824","name":"大谷家住宅主屋","kana":"おおたにけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県深谷市稲荷町2-3-39","lat":36.194847,"lng":139.291397,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積286㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0071","desc":"南北棟・２階建の南棟と，東西棟・平屋建の北棟からなり，南棟に玄関を設ける。屋根は桟瓦葺で，庇などを銅板葺とする。良材を用いた質の高い数奇屋風建物で，要所にステインドグラスを配する。造作から建具に至るまで，高度で精緻な技量が発揮されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003834"},{"id":"00003837","register_sub_id":"101","register_pk":"104827","name":"大谷家住宅松庭湯","kana":"おおたにけじゅうたくしょうていゆ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県深谷市稲荷町2-3-39","lat":36.194927,"lng":139.291534,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.0㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0074","desc":"敷地の北東隅に設けられた屋外の浴室で，主屋と同時期に建てられた。約１間四方の小規模な建物で，屋根は切妻造，銅板葺，三方を板壁で囲むが，庭園を望む南面を吹放しとする。簡素であるが，主屋の造形に通じる数奇屋風の軽快なつくりになっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003837"},{"id":"00003839","register_sub_id":"101","register_pk":"104829","name":"大谷家住宅中門及び塀","kana":"おおたにけじゅうたくちゅうもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県深谷市稲荷町2-3-39","lat":36.19461859,"lng":139.29136479,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造、瓦葺、間口2.4m、塀延長28m","structure_material":"木造","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0076","desc":"主屋及び洋館の南正面を囲う。中門は１間１戸棟門で，屋根は起りのある切妻造，桟瓦葺とし，扉板や欄間の透かし彫及び木舞打の化粧屋根裏など，瀟洒な数奇屋風意匠である。中門左右の塀も真壁造で，腰に用いた名栗，透かし彫り欄間など，凝ったつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003839"},{"id":"00003838","register_sub_id":"101","register_pk":"104828","name":"大谷家住宅祠","kana":"おおたにけじゅうたくほこら","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県深谷市稲荷町2-3-39","lat":36.1948457,"lng":139.29127952,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積0.37㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0075","desc":"敷地の西辺，主屋と本蔵に囲まれた坪庭にある。乱石積基壇上に，台座風の御影石を２段に積み重ね，建物を載せる。方１間，入母屋造，妻入で，軒は一軒繁垂木，屋根は瓦棒銅板葺とする。三斗組，正面の蟇股，絵様木鼻など，小規模だが本格的なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003838"},{"id":"00003836","register_sub_id":"101","register_pk":"104826","name":"大谷家住宅本蔵","kana":"おおたにけじゅうたくほんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県深谷市稲荷町2-3-39","lat":36.19494555,"lng":139.29131358,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積69㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0073","desc":"主屋北棟の西側にある。桁行７間，梁間３間，南北棟の切妻造，桟瓦葺の２階建土蔵で，東面の戸前を廊下として主屋と連続する。１階は２室に分れ，２階は１２畳敷を備え蔵座敷とするが，簡素である。全体に堅固なつくりで，漆喰塗なども丁寧な仕上げである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003836"},{"id":"00003835","register_sub_id":"101","register_pk":"104825","name":"大谷家住宅洋館","kana":"おおたにけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県深谷市稲荷町2-3-39","lat":36.19465481,"lng":139.29126742,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積22㎡","structure_material":"木造2階一部平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0072","desc":"主屋南棟の南妻面に接続した木造２階建で，半切妻状屋根はスペイン瓦葺，外壁は人造石洗い出しで，上部をハーフティンバー風に扱い，ステインドグラス入りの縦長窓とする。ユーゲント・シュティルのスタイルで纏められた瀟洒な洋館で，内装もよく残っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003835"},{"id":"00007189","register_sub_id":"101","register_pk":"108171","name":"岡野家住宅土蔵","kana":"おかのけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県入間郡越生町大字越生字町796","lat":35.96290756,"lng":139.29835685,"geo_status":"db","era":"明治期／大正6増築","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"11 － 0122","desc":"店蔵の東方、敷地奥に建つ。桁行６．３ｍ梁間３．６ｍの土蔵造２階建。壁は白漆喰仕上げ。東西棟の切妻造妻入桟瓦葺とし、西妻面に庇を掛け、出入口を設ける。入口の西南に、東西棟の切妻屋根を付け、桁行３．３ｍ梁間１．６ｍの湯殿をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007189"},{"id":"00007188","register_sub_id":"101","register_pk":"108170","name":"岡野家住宅店蔵","kana":"おかのけじゅうたくみせぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県入間郡越生町大字越生字町796","lat":35.96291665,"lng":139.29812599,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積53㎡","structure_material":"土蔵造3階建","registered":"2008.07.08(平成20.07.08)","register_no":"11 － 0121","desc":"通りに西面して建つ、土蔵造３階建。屋根は切妻造桟瓦葺。桁行３間半梁間３間半で、正面に奥行１間の下屋が付く。当初の外壁は黒漆喰で仕上げられた。１階戸袋には亀甲崩しの文様が銅板で作られ、軒が出桁造で２階のみ垂木形を表すなど、意匠性に富む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007188"},{"id":"00014138","register_sub_id":"101","register_pk":"508768","name":"恩田家住宅主屋","kana":"おんだけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県八潮市大字二丁目字上190","lat":35.82397778,"lng":139.84641944,"geo_status":"db","era":"大正6年／昭和41年・平成2年改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積237㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"11 - 0216","desc":"中川低地の農家で屋敷林を背後に有する。平屋建寄棟造桟瓦葺で南西に下屋を廻し、入母屋造玄関を付す。西半を続き座敷と居間として縁を廻らし、東半は元土間。欅の大黒柱やせいの高い差物等、堅牢な造りとし、座敷書院は組子等に繊細な細部意匠を併せ持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014138"},{"id":"00014139","register_sub_id":"101","register_pk":"508769","name":"恩田家住宅蔵","kana":"おんだけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県八潮市大字二丁目字上190","lat":35.82415833,"lng":139.846475,"geo_status":"db","era":"明治30年","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積98㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"11 - 0217","desc":"中川低地の農家の倉庫で主屋の東に位置する。桁行９間梁間３間、切妻造桟瓦葺。真壁造南北棟で西面し西に下屋を付し舟を吊る。内部は北半を土間、南半を板敷２室とし、それぞれ戸口を設ける。南から第二室は米を貯蔵した。水害予備船を備えて地域性を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014139"},{"id":"00011875","register_sub_id":"101","register_pk":"211125","name":"加藤家住宅主屋","kana":"かとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県さいたま市岩槻区大字古ヶ場字白水68","lat":35.980802,"lng":139.695842,"geo_status":"db","era":"安政6年（1859）頃／明治12年増築、昭和59年・同61年頃改修","year":1859,"year_source":"db","year_min":1859,"year_max":1859,"year_label":null,"structure":"木造2階建、銅板葺、建築面積185㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"11-171","desc":"市内北東部にあり敷地中央に南面する。桁行一一間半、梁間七間半、寄棟造とする。内部は東半を土間とし、床上部は二列六室で、土間沿いのブツマには、打壊しに備えて建込んだ格子戸が四周に残る。平書院を付けた上質な座敷をもつ大規模農家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011875"},{"id":"00009904","register_sub_id":"101","register_pk":"196051","name":"旧新井家住宅石垣","kana":"きゅうあらいけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県日高市大字高麗本郷字上ノ原245他","lat":35.88621947,"lng":139.31089043,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"石造、延長62m","structure_material":"石造","registered":"2014.04.25(平成26.04.25)","register_no":"11 － 0140","desc":"屋敷地の南面から納屋東面に矩折れに積まれた石垣。野面石積、延長六二メートルで、最大高さ二・八メートルを測る。法面に緩やかな弛みをもたせ、隅は算木積風に積む。小高い敷地の形状を巧みに利用し、巾着田から見上げた際の屋敷構えを強く印象づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009904"},{"id":"00009903","register_sub_id":"101","register_pk":"196050","name":"旧新井家住宅北土蔵","kana":"きゅうあらいけじゅうたくきたどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県日高市大字高麗本郷字上ノ原245","lat":35.88655513,"lng":139.31086349,"geo_status":"db","era":"明治中期／平成24改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"11 － 0139","desc":"主屋北方の小高い石垣の上に西面して建つ。桁行五・五メートル梁間三・六メートル、土蔵造二階建、置屋根形式の桟瓦葺で、西面に下屋を設ける。土台を廻さず礎石建とし、一階を土間とする。土間には甕が埋められ、もとは食料品等の貯蔵蔵と考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009903"},{"id":"00009900","register_sub_id":"101","register_pk":"196047","name":"旧新井家住宅客殿","kana":"きゅうあらいけじゅうたくきゃくでん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"埼玉県","address":"埼玉県日高市大字高麗本郷字上ノ原245","lat":35.88635384,"lng":139.31064062,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造2階建、瓦葺、建築面積93㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"11 － 0136","desc":"主屋南西側に東面して建つ。木造二階建で、一階正面に唐破風造の車寄を設ける。一階に四室と湯殿、便所を、二階に三室を配し、各々南端室を客間とする。客間は高欄を付けて巾着田への良好な眺望を得るとともに、トコ、違棚、付書院を付した瀟洒な空間とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009900"},{"id":"00009899","register_sub_id":"101","register_pk":"196046","name":"旧新井家住宅主屋","kana":"きゅうあらいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県日高市大字高麗本郷字上ノ原245","lat":35.88644772,"lng":139.31084221,"geo_status":"db","era":"明治中期／平成5・平成24改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積318㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"11 － 0135","desc":"高麗川で囲まれた巾着田を見下ろす高台上に南面して建つ。主体部が桁行二三メートルを測る大規模な二階建住宅。平面は整型六間取で、広い土間を持ち、背面に書斎と物置等を張出す。デイ、オクは天井を一段高くし、トコと違棚、付書院を設けて格式を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009899"},{"id":"00009901","register_sub_id":"101","register_pk":"196048","name":"旧新井家住宅納屋","kana":"きゅうあらいけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県日高市大字高麗本郷字上ノ原245","lat":35.88626259,"lng":139.31104564,"geo_status":"db","era":"明治21／平成24改修","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"11 － 0137","desc":"敷地南側中央の石垣上に建ち、桁行一一メートル梁間四・五メートルを測る。小屋は和小屋で、壁は漆喰塗とし、腰に簓子下見板を張る。南東面では与力窓を横に並べ、風格のある印象を与える。優美な軒反を見せ、巾着田から見上げた際の屋敷構えを引き立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009901"},{"id":"00009902","register_sub_id":"101","register_pk":"196049","name":"旧新井家住宅南土蔵","kana":"きゅうあらいけじゅうたくみなみどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県日高市大字高麗本郷字上ノ原245","lat":35.88637396,"lng":139.3111548,"geo_status":"db","era":"明治中期／平成24改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"11 － 0138","desc":"主屋の東方に西面して建つ。桁行六・四メートル梁間四・五メートル、土蔵造二階建、切妻造、置屋根式の桟瓦葺である。小屋は和小屋を組み、もとは家財道具を収納するために使用した。西面に比較的大きな下屋を設け、納屋とともに屋敷の表構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009902"},{"id":"00003821","register_sub_id":"101","register_pk":"104811","name":"旧新井商店倉庫","kana":"きゅうあらいしょうてんそうこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"埼玉県","address":"埼玉県秩父市本町1400","lat":35.99683143,"lng":139.08233092,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積2２㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0058","desc":"屋敷後方，主屋南に並んで建つ。東西棟の切妻造，妻入，桟瓦葺，２階建で，外壁は漆喰塗とする。東面は戸前の庇を架け，西面は下屋を設けて漆喰壁を廻し物置とする。軒は二重に鉢巻きを廻し，２階窓には鉄格子を入れ鉄扉をつけるなど，堅固なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003821"},{"id":"00002358","register_sub_id":"101","register_pk":"103348","name":"旧鋳物問屋鍋平別邸蔵","kana":"きゅういものどんやなべへいべっていくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県川口市金山町15-2","lat":35.795815,"lng":139.722382,"geo_status":"db","era":"昭和2頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積29㎡","structure_material":"木造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"11 － 0031","desc":"主屋の北西に建つ土蔵。米蔵として主屋玄関脇の応接間等とともに増築され，後に内部に床を増設して二層に改めた。２間×３間の小規模な蔵だが，外壁はモルタル塗りに目地を切り石造風に見せ，軒蛇腹，胴蛇腹を付けて外観を整えるなど，丁寧な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002358"},{"id":"00002356","register_sub_id":"101","register_pk":"103346","name":"旧鋳物問屋鍋平別邸主屋","kana":"きゅういものどんやなべへいべっていしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県川口市金山町15-2","lat":35.79569501,"lng":139.72252457,"geo_status":"db","era":"明治45頃／昭和2頃増築","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階建、瓦葺、建築面積200㎡","structure_material":"木造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"11 － 0029","desc":"鋳物問屋嶋崎家の別邸として建設された。数度による増改築により複雑な平面・外観を呈すが，玄関から東半の１階部分が創建当初の箇所である。座敷は床，棚，書院を備えた本格的な構えで，亀甲模様の書院窓や透彫り欄間など，数寄屋風の凝った意匠で飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002356"},{"id":"00002357","register_sub_id":"101","register_pk":"103347","name":"旧鋳物問屋鍋平別邸離れ","kana":"きゅういものどんやなべへいべっていはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県川口市金山町15-2","lat":35.79569936,"lng":139.72262671,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積82㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"11 － 0030","desc":"主屋の東に増設された平屋建の建物。１０畳の座敷の北面に床・棚・書院を備え，その他三方に縁を回らし，北に便所を付属する。座敷回りは輸入された銘木やガラスを多用し，洋式の便所は外観を洋風にまとめ，内部をモザイクタイル等で飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002357"},{"id":"00012701","register_sub_id":"101","register_pk":"367604","name":"旧大野家住宅主屋","kana":"きゅうおおのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県越谷市越ヶ谷本町4552-1","lat":35.89377389,"lng":139.78505694,"geo_status":"db","era":"明治38年頃／平成元年頃・同30年改修","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造2階建、瓦葺、建築面積162㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"11 － 187","desc":"市中心部のもと商家で、主屋は旧日光街道に西面して建つ。切妻造桟瓦葺の二階建で、背面の寄棟造の角屋に客座敷を設ける。正面は木太い梁の出桁造とし、吹放しの下屋全面に繊細な格子を備えるなど丁寧なつくりとする。宿場町の景観を伝える貴重な町家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012701"},{"id":"00012702","register_sub_id":"101","register_pk":"367605","name":"旧大野家住宅土蔵","kana":"きゅうおおのけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県越谷市越ヶ谷本町4552-1","lat":35.89377389,"lng":139.78505694,"geo_status":"db","era":"明治中期／平成30年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積36㎡、渡廊下付","structure_material":"土蔵造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"11 － 188","desc":"主屋背面に建つ旧座敷蔵。土蔵造二階建、東西棟の切妻造桟瓦葺で西南二面に下屋を廻し、各面に戸口を設ける。外壁は黒漆喰塗、内部は上下階とも板敷。柱を半間毎に立て、小屋組を二重梁とするなど堅牢につくる。商家の伝統的な屋敷構えを構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012702"},{"id":"00014741","register_sub_id":"101","register_pk":"518999","name":"旧長島家住宅裏蔵","kana":"きゅうながしまけじゅうたくうらぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県熊谷市小八林字大境1022","lat":36.07957222,"lng":139.43678611,"geo_status":"db","era":"大正3年頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"石造2階建、瓦葺、建築面積53㎡","structure_material":"石造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"11 - 0225","desc":"主屋の北に南面して建つ座敷蔵。石造二階建、切妻造桟瓦葺で、外壁は大谷石を積む。基礎を石積で嵩上げし、南に戸口を二箇所開け、下屋を付す。内部は一階二室、二階三室で、床下にも収納を設ける。実用性と意匠性を兼ねた土蔵で敷地後背部の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014741"},{"id":"00014742","register_sub_id":"101","register_pk":"519000","name":"旧長島家住宅表門","kana":"きゅうながしまけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県熊谷市小八林字大境1022","lat":36.07919167,"lng":139.43708611,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口2.8m","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"11 - 0226","desc":"敷地南辺東寄り、米蔵と長屋塀の間に南面して建つ門。間口二・八メートルの一間一戸薬医門で東西に袖塀を設け、東に潜戸を開く。屋根は反りを持つ切妻造桟瓦葺。主柱と控柱に渡した梁上の束で棟木を受ける。旧家の表門として敷地正面景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014742"},{"id":"00014738","register_sub_id":"101","register_pk":"518996","name":"旧長島家住宅主屋","kana":"きゅうながしまけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県熊谷市小八林字大境1022","lat":36.07948889,"lng":139.43688333,"geo_status":"db","era":"江戸後期／昭和20年頃増築、同50年頃・平成2年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺（銅板仮葺）一部瓦葺、建築面積209㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"11 - 0222","desc":"当家は名主を務めた旧家で、敷地は荒川右岸の田園地帯に位置する。主屋は敷地の中央東寄りに南面して建つ。木造平屋建、茅葺（銅板仮葺）、一部瓦葺の下屋を付す。東に広い土間、西に田の字形に部屋を配す。西に角座敷を設け上段の間とし、旧家の風格を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014738"},{"id":"00014743","register_sub_id":"101","register_pk":"519001","name":"旧長島家住宅木戸門","kana":"きゅうながしまけじゅうたくきどもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県熊谷市小八林字大境1022","lat":36.07941389,"lng":139.436925,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口1.5m","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"11 - 0227","desc":"主屋前方の庭園東辺を仕切る塀の間に設けた門。切妻造桟瓦葺で、間口一・五メートルの腕木門。主柱で棟木を支持し、女梁、男梁風の腕木を重ねて軒桁を受け、反りのある垂木を架ける。門口には両開きの板戸を吊る。小規模ながら庭園と敷地の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014743"},{"id":"00014739","register_sub_id":"101","register_pk":"518997","name":"旧長島家住宅米蔵","kana":"きゅうながしまけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県熊谷市小八林字大境1022","lat":36.07924722,"lng":139.43715,"geo_status":"db","era":"大正9年頃／昭和60年頃改修","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"石造2階建、瓦葺、建築面積50㎡","structure_material":"石造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"11 - 0223","desc":"敷地南東隅に位置し、塀を介し表門と並んで建つ米蔵。石造二階建、切妻造桟瓦葺、外壁は大谷石を積み、小屋は木造トラス組。内部は一室で一階北面に入口を、二階南面に窓を二箇所設け、各々鉄扉を付す。表門、長屋塀と共に敷地南面の景観を形成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014739"},{"id":"00014745","register_sub_id":"101","register_pk":"519003","name":"旧長島家住宅外塀","kana":"きゅうながしまけじゅうたくそとべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県熊谷市小八林字大境1022","lat":36.07933333,"lng":139.436475,"geo_status":"db","era":"大正9年頃","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"石造、総延長136m","structure_material":"石造","registered":"2024.03.06(令和6.03.06)","register_no":"11 - 0229","desc":"敷地北面及び西面に沿って建つ石塀。西面八〇・八メートル、北面五五・五メートルで総延長は一三六・三メートル。自然石積の基礎の上に、直方体に加工した大谷石を六段積、最上部に大谷石の笠木を置く。敷地を区画する長大な塀で、歴史的な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014745"},{"id":"00014744","register_sub_id":"101","register_pk":"519002","name":"旧長島家住宅長屋塀","kana":"きゅうながしまけじゅうたくながやべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県熊谷市小八林字大境1022","lat":36.07910833,"lng":139.4369,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積72㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"11 - 0228","desc":"表門の西に接続して建つ、塀を兼ねた長大な倉庫。木造平屋建、切妻造桟瓦葺、外壁は白漆喰塗仕上、腰は大谷石張とする。梁間一間、桁行二一間の中央一間を戸口として板戸を吊り、東西に各三室配す。南面に各室一箇所等間隔に窓を穿ち、敷地正面を印象付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014744"},{"id":"00014740","register_sub_id":"101","register_pk":"518998","name":"旧長島家住宅前蔵","kana":"きゅうながしまけじゅうたくまえぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県熊谷市小八林字大境1022","lat":36.079375,"lng":139.43708889,"geo_status":"db","era":"大正9年／平成4年改修","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"石造2階建、瓦葺、建築面積59㎡","structure_material":"石造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"11 - 0224","desc":"敷地東辺に沿って、主屋と米蔵の間に西面して建つ蔵。石造二階建、切妻造桟瓦葺、外壁は大谷石を積み、小屋はトラス組。桁行が長く、正側面に下屋を付す。内部は一室で一階西面に入口を二箇所設け各々鉄扉を付す。表門から主屋へ続く邸内景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014740"},{"id":"00013954","register_sub_id":"101","register_pk":"508214","name":"旧中村家住宅石蔵","kana":"きゅうなかむらけじゅうたくいしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県越谷市大間野町一丁目100-4","lat":35.86312778,"lng":139.78196111,"geo_status":"db","era":"昭和前期／平成13年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"石造平屋建、瓦葺、建築面積37㎡","structure_material":"石造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"11 - 0210","desc":"主屋南東に位置する切妻造桟瓦葺の石蔵。石造の東西棟で軒廻の蛇腹まで石を丁寧に積上げる。西面に下屋を付して戸口とし、西と南に窓を一箇所づつ開ける。内部は一室の土間で石敷とし、上部は二重に梁を重ねた和小屋を現す。敷地南東の景観を構成する石蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013954"},{"id":"00013951","register_sub_id":"101","register_pk":"508211","name":"旧中村家住宅主屋","kana":"きゅうなかむらけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県越谷市大間野町一丁目100-4","lat":35.86335,"lng":139.78180556,"geo_status":"db","era":"大正3年／平成15年改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積218㎡、裏木戸付","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"11 - 0207","desc":"越谷市南端の大間野町に位置し、敷地中央北寄りに南面する平屋建寄棟造桟瓦葺。四周に下屋を廻し、南面西端に入母屋造の式台を付す。東半は土間、西半は三列五室とし、西列は床廻りに銘木を用いた続き間座敷とする。旧家の興隆を伝える上質な近代の主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013951"},{"id":"00013953","register_sub_id":"101","register_pk":"508213","name":"旧中村家住宅土蔵","kana":"きゅうなかむらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県越谷市大間野町一丁目100-4","lat":35.86343611,"lng":139.781675,"geo_status":"db","era":"明治27年／平成13年改修","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積43㎡","structure_material":"土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"11 - 0209","desc":"主屋の北西に建つ二階建切妻造桟瓦葺の南北棟。南妻に窓を開け、東以外の三方に庇を巡らし、外壁は漆喰塗仕上とする。東は下屋を付して戸口とし、掛子塗戸を建てる。一、二階とも一室の板敷で、一階床は大引上端を床板と同一面に現す特徴的なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013953"},{"id":"00013956","register_sub_id":"101","register_pk":"508216","name":"旧中村家住宅長屋門","kana":"きゅうなかむらけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県越谷市大間野町一丁目100-4","lat":35.86306389,"lng":139.78180556,"geo_status":"db","era":"明治19年／平成15年改修","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積81㎡、左右袖塀付","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"11 - 0212","desc":"敷地南辺中央に位置する平屋建寄棟造桟瓦葺で、東西に袖塀を延ばす。中央を門口とし、西は土間の一室、東は二室で西を板敷、東を土間とする。外壁は真壁造で鼠漆喰仕上とし、腰に下見板を張る。門口に錺金具を打った両開戸を吊り、旧家の風格を示す長屋門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013956"},{"id":"00013952","register_sub_id":"101","register_pk":"508212","name":"旧中村家住宅納屋","kana":"きゅうなかむらけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県越谷市大間野町一丁目100-4","lat":35.86341667,"lng":139.7819,"geo_status":"db","era":"明治21年／平成15年改修","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"11 - 0208","desc":"主屋北東に南面する木造平屋建切妻造桟瓦葺の東西棟。外壁は真壁造で漆喰塗仕上とし、北と東は下見板張。東半は土間の味噌部屋で南に戸口を設け、上部は小屋組を現す。西半は板敷の道具部屋で天井を張り、北に押入を設ける。敷地北東の景観をつくる納屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013952"},{"id":"00013955","register_sub_id":"101","register_pk":"508215","name":"旧中村家住宅御嶽社","kana":"きゅうなかむらけじゅうたくみたけしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"埼玉県","address":"埼玉県越谷市大間野町一丁目100-4","lat":35.86328889,"lng":139.78156944,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、銅板葺、建築面積3.4㎡、覆屋付","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"11 - 0211","desc":"主屋の西に位置し、四周吹放ちの方一間入母屋造銅板葺の覆屋を附属する。本体は切石積基壇に建つ方一間切妻造妻入で東面する。正面側の螻羽を延ばして向拝とし、正側面に高欄付縁を廻らせ脇障子を入れる。随所に彫刻を施し小社ながら精緻な造りの御嶽社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013955"},{"id":"00015411","register_sub_id":"101","register_pk":"533426","name":"旧山﨑家住宅（油長）内蔵","kana":"きゅうやまざきけじゅうたくあぶらちょううちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県越谷市越ヶ谷三丁目4663-6","lat":35.89205833,"lng":139.78718056,"geo_status":"db","era":"江戸後期／平成27年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"11 - 0235","desc":"越ヶ谷宿中心部に移築したかつての肥料商の家財蔵である。通りに北面して建つ二階建切妻造平入桟瓦葺で大棟を高く積み、外壁は漆喰塗、腰はモルタル塗仕上とする。内部は各階一室で、小屋は束立の和小屋とする。窓に掛子塗扉を付し小規模ながら重厚な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015411"},{"id":"00009581","register_sub_id":"101","register_pk":"194577","name":"旧和田家住宅（クロスケの家）主屋","kana":"きゅうわだけじゅうたく（くろすけのいえ）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県所沢市三ケ島3-1169-1","lat":35.79118299,"lng":139.40708924,"geo_status":"db","era":"明治35頃／昭和32移築・平成23改修","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造2階建、瓦葺、建築面積211㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"11 － 0127","desc":"敷地中央に南面して建ち、木造二階建、切妻造桟瓦葺で、周囲に下屋を廻らせる。東半に土間と事務所を配し、西側の床上部は整型四間取を基本として背面に奥行一間半の下屋を通す。狭山茶の製茶に用いた広い土間をもつなど県南丘陵部の民家の特徴を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009581"},{"id":"00009582","register_sub_id":"101","register_pk":"194578","name":"旧和田家住宅（クロスケの家）製茶工場","kana":"きゅうわだけじゅうたく（くろすけのいえ）せいちゃこうじょう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"埼玉県","address":"埼玉県所沢市三ケ島3-1166-2","lat":35.79094214,"lng":139.40712107,"geo_status":"db","era":"明治35／昭和26増築","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積169㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"11 － 0128","desc":"主屋西隣に東西棟で建ち、木造平屋建、切妻造鋼板葺で、東面と南面を下屋とする。北西寄りの桁行七間梁間三間分が当初の蚕室部で、小屋に二層の簀子床を張る。養蚕用に建てられ、後に製茶工場とするため拡張された経緯をとどめ、生業の変遷過程を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009582"},{"id":"00009583","register_sub_id":"101","register_pk":"194579","name":"旧和田家住宅（クロスケの家）土蔵","kana":"きゅうわだけじゅうたく（くろすけのいえ）どぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県所沢市三ケ島3-1169-1","lat":35.79117109,"lng":139.4068156,"geo_status":"db","era":"明治20頃／明治35頃移築・平成20改修","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"11 － 0129","desc":"主屋南側に東西棟で建ち、土蔵造二階建、置屋根式の桟瓦葺である。北西面に、茶葉乾燥用のノキバと称する下屋を廻らす。外壁は腰を洗出し仕上げ、上部を漆喰塗として水切を廻らし、北面の上下階に二箇所ずつ窓と戸口を設ける。茶農家の屋敷構えを整える土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009583"},{"id":"00016358","register_sub_id":"101","register_pk":"536425","name":"小山家住宅主屋","kana":"こやまけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県さいたま市見沼区大字小深作字小深作前353他","lat":35.944625,"lng":139.66475833,"geo_status":"db","era":"明治中期／大正後期増築、昭和20年代・同50年代改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積145㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"11 - 0236","desc":"市街地北東の丘陵地に位置する農家の主屋。敷地中央に南面する2階建寄棟造平入桟瓦葺で、一階は東に土間、西に4室を配して北西室に床を構え、北西に角屋を付す。二階はかつて蚕室とし上部に和小屋を現す。伝統的な間取りを残し、地域景観の核となる民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016358"},{"id":"00016359","register_sub_id":"101","register_pk":"536426","name":"小山家住宅蔵","kana":"こやまけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県さいたま市見沼区大字小深作字小深作前353他","lat":35.94458333,"lng":139.66459444,"geo_status":"db","era":"明治前期／平成3年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"11 - 0237","desc":"主屋の西方に東面して建つ農具用の土蔵。2階建切妻造平入桟瓦葺で、正面に下屋を付す。外壁は大壁で軒まで塗り込める。内部は各階一室の板敷で、二階上部に現す小屋組は束立の和小屋とする。窓少なく閉鎖的な構えの土蔵で、敷地北側の歴史的な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016359"},{"id":"00013045","register_sub_id":"101","register_pk":"368351","name":"齋藤家住宅主屋","kana":"さいとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県北足立郡伊奈町大字小針新宿字上宿227","lat":36.00856944,"lng":139.59363889,"geo_status":"db","era":"江戸末期／昭和57年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（金属板仮葺）、建築面積164㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"11 － 0191","desc":"旧往還西側の短冊状敷地に東面して建つ平屋建。南面を除く三面に下屋の縁を廻らし、内部は南側が土間で床上部を六間取とする。表列上手のオクノマに主座敷として床などを備えて長押を廻らし、他は差鴨居などで柱を固める。往時の農村景観を伝える農家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013045"},{"id":"00016650","register_sub_id":"101","register_pk":"579134","name":"芝﨑家住宅表門","kana":"しばさきけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県川口市本町一丁目51-1","lat":35.797697,"lng":139.724615,"geo_status":"db","era":"江戸末期／昭和17年移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口1.7m、袖塀付","structure_material":"木造","registered":"2026.07.09(令和8.07.09)","register_no":"11 - 0250","desc":"敷地の南面中央に開く表門。通りから引き込み建つ、切妻造桟瓦葺の一間薬医門で親柱と控柱を貫で固め、冠木から控柱上の桁へ３筋の梁を架ける。束で棟木を受け、梁先端で軒を支持する。門口に八双金具付の板扉を吊る。欅の良材を用い、旧家の格式を示す表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016650"},{"id":"00016648","register_sub_id":"101","register_pk":"579132","name":"芝﨑家住宅主屋","kana":"しばさきけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県川口市本町一丁目51-1他","lat":35.797888,"lng":139.724529,"geo_status":"db","era":"江戸末期／大正後期・令和元年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積140㎡","structure_material":"木造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"11 - 0248","desc":"市街地中心部に位置する旧家の主屋。敷地中央に南面して建つ二階建寄棟造平入桟瓦葺。東を土間、西に部屋を田の字に配し、南・西に縁を廻らす。北西の座敷は床、床脇に天袋と違棚、付書院を備え、組子の欄間など繊細なつくり。地域景観をつくる上質な主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016648"},{"id":"00016649","register_sub_id":"101","register_pk":"579133","name":"芝﨑家住宅離れ","kana":"しばさきけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県川口市本町一丁目51","lat":35.797742,"lng":139.724696,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積48㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"11 - 0249","desc":"敷地南東に位置する離れ。南面して建つ、寄棟造桟瓦葺で正面に縁を設けて、下屋を付す。外壁は漆喰塗仕上、押縁下見板を高く張る。内部は東に踏込土間の玄関を設け、西に六畳の仏間、八畳の座敷を並べる。全体に簡素なつくりながら、敷地南東の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016649"},{"id":"00002017","register_sub_id":"101","register_pk":"103007","name":"島村家住宅土蔵","kana":"しまむらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県桶川市寿2-1-4","lat":36.0009294,"lng":139.56611986,"geo_status":"db","era":"天保7","year":1836,"year_source":"db","year_min":1836,"year_max":1836,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積71㎡","structure_material":"土蔵造3階建","registered":"2000.12.04(平成12.12.04)","register_no":"11 － 0028","desc":"中山道桶川宿における名家の土蔵で，天保飢饉の「お助け蔵」として知られる。桁行６間，梁行３間規模，切妻造，桟瓦葺の総３階建土蔵で，東面下屋庇を蔵前とするが，当初は主屋側の南妻面を入口とする妻入土蔵であった。市内現存最古の建造物のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002017"},{"id":"00011072","register_sub_id":"101","register_pk":"205179","name":"睡足軒","kana":"すいそくけん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"埼玉県","address":"埼玉県新座市野火止一丁目1172-1","lat":35.789425,"lng":139.562411,"geo_status":"db","era":"江戸後期／昭和13移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、鉄板葺、建築面積93㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"11 - 0157","desc":"平林寺の境内林内に東西棟で建つ。飛騨地方から移築した民家で、梁間一杯のイロリノマの東西に二室ずつ配る。木太い軸部構成、チョウナ梁の架構や両妻の股柱の採用に飛騨の民家の特色を伝えるとともに、造作の意匠などに昭和初期の民家活用の嗜好を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011072"},{"id":"00011266","register_sub_id":"101","register_pk":"209102","name":"鈴木家住宅主屋","kana":"すずきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県比企郡川島町大字宮前字根本308-1","lat":35.977135,"lng":139.490694,"geo_status":"db","era":"江戸中期／安政2増築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋一部2階建、茅葺、建築面積207㎡","structure_material":"木造平屋一部2階建","registered":"2016.11.29(平成28.11.29)","register_no":"11－0158","desc":"田園地帯の敷地に南面して建つ茅葺民家。東半を占める土間部の東西棟と西半の床上部の棟を直交させ、床上部南側に入母屋の妻を見せる。床上部は整型四間取で前列西室に床を構える。土間の湾曲した細い梁組などに古様を示し、当地の近世上層農家の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011266"},{"id":"00011267","register_sub_id":"101","register_pk":"209103","name":"鈴木家住宅土蔵","kana":"すずきけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県比企郡川島町大字宮前字根本308-1","lat":35.977076,"lng":139.490863,"geo_status":"db","era":"明治10頃","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"11－0159","desc":"主屋東側に南北棟で建つ。土蔵造二階建、桁行七・三メートル梁間四・五メートル、置屋根式の切妻造桟瓦葺で、小屋野地に割竹を並べる技法に地方色を示す。一階南妻の戸口に下屋を設け漆喰塗の重厚な扉を開く。主屋と共に農家の屋敷構えを形成する、もと米蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011267"},{"id":"00013949","register_sub_id":"101","register_pk":"508209","name":"須田家住宅（中屋）土蔵","kana":"すだけじゅうたく（なかや）どぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県草加市住吉一丁目61-1","lat":35.82979444,"lng":139.80673333,"geo_status":"db","era":"明治後期／平成28年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積44㎡","structure_material":"土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"11 - 0205","desc":"旧日光街道草加宿の商家の土蔵で東西に長い敷地中央に建つ。土蔵造二階建、切妻造桟瓦葺。南面に下屋を付して掛子塗の両開土戸を建てる。二階は両開鉄扉付の格子窓を二箇所開ける。内部は一、二階とも一室。染料の売買で繁栄した商家の丁寧なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013949"},{"id":"00003827","register_sub_id":"101","register_pk":"104817","name":"薗田家住宅表門","kana":"そのだけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県秩父市番場町994-1","lat":35.99604721,"lng":139.08388824,"geo_status":"db","era":"天保年間","year":1837,"year_source":"estimated","year_min":1830,"year_max":1844,"year_label":"天保年間","structure":"木造、瓦葺、間口3.0m、袖塀付","structure_material":"木造","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0064","desc":"敷地東辺にある。１間１戸四脚門形式で，屋根は南北棟の切妻造，桟瓦葺，南妻に潜戸を設ける。長方形断面の親柱から垂木まで欅材をふんだんに用いた丁寧なつくりである。南北には桟瓦葺屋根付の板壁を延ばす。風格のある屋敷正面の構えをかたちづくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003827"},{"id":"00003826","register_sub_id":"101","register_pk":"104816","name":"薗田家住宅主屋","kana":"そのだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県秩父市番場町994-1","lat":35.99615597,"lng":139.08361871,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造2階建、瓦葺、建築面積252㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0063","desc":"明治末期頃に武甲山麓の民家の部材を用いて建設したと伝える。東面して建つ木造総２階建，南北棟の切妻造，桟瓦葺，平入で，平面は基本的に整形４間取とする。正面の東面中央に式台を備え，入母屋造屋根の玄関を突出し，社家らしい雰囲気のある外観をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003826"}];
